create or replace function public.reorder_itinerary_items(
  target_day_id uuid,
  ordered_item_ids uuid[]
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_trip_id uuid;
  existing_count integer;
begin
  select route_variants.trip_id
  into target_trip_id
  from public.trip_days
  join public.route_variants on route_variants.id = trip_days.variant_id
  where trip_days.id = target_day_id;

  if target_trip_id is null or not public.is_trip_owner(target_trip_id) then
    raise exception 'Trip owner access required' using errcode = '42501';
  end if;

  if ordered_item_ids is null then
    raise exception 'Item order is required' using errcode = '22023';
  end if;

  select count(*) into existing_count
  from public.itinerary_items
  where day_id = target_day_id;

  if cardinality(ordered_item_ids) <> existing_count
    or (select count(distinct item_id) from unnest(ordered_item_ids) as item_id) <> existing_count
    or exists (
      select 1
      from unnest(ordered_item_ids) as submitted(item_id)
      left join public.itinerary_items
        on itinerary_items.id = submitted.item_id
        and itinerary_items.day_id = target_day_id
      where itinerary_items.id is null
    )
  then
    raise exception 'Submitted items must exactly match the day itinerary' using errcode = '22023';
  end if;

  update public.itinerary_items
  set sort_order = submitted.position - 1
  from unnest(ordered_item_ids) with ordinality as submitted(item_id, position)
  where itinerary_items.id = submitted.item_id;
end;
$$;

-- Source: supabase/migrations/20260729220000_flexible_itinerary_workflow.sql
create type public.itinerary_schedule_kind as enum (
  'none',
  'all_day',
  'period',
  'approximate',
  'exact',
  'range'
);

alter table public.itinerary_items
  add column schedule_kind public.itinerary_schedule_kind not null default 'none',
  add column schedule_text text,
  add constraint itinerary_items_schedule_consistency check (
    (schedule_kind in ('none', 'all_day') and start_time is null and end_time is null)
    or (schedule_kind in ('period', 'approximate') and schedule_text is not null and start_time is null and end_time is null)
    or (schedule_kind = 'exact' and start_time is not null and end_time is null)
    or (schedule_kind = 'range' and start_time is not null and end_time is not null and end_time >= start_time)
  ) not valid;

update public.itinerary_items
set schedule_kind = case
  when start_time is not null and end_time is not null then 'range'::public.itinerary_schedule_kind
  when start_time is not null then 'exact'::public.itinerary_schedule_kind
  else 'none'::public.itinerary_schedule_kind
end;

alter table public.itinerary_items
  validate constraint itinerary_items_schedule_consistency;

