create function public.save_day_route_plan(
  target_day_id uuid,
  target_variant_id uuid,
  ordered_item_ids uuid[],
  requested_leg_modes text[]
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_trip_id uuid;
  saved_plan_id uuid;
  submitted_count integer := coalesce(cardinality(ordered_item_ids), 0);
  mode_count integer := coalesce(cardinality(requested_leg_modes), 0);
  duplicate_group_count integer;
  invalid_duplicate_count integer;
  distinct_location_count integer;
begin
  if app_private.app_current_user_id() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select variant.trip_id into target_trip_id
  from public.trip_days day
  join public.route_variants variant on variant.id = day.variant_id
  where day.id = target_day_id
    and day.variant_id = target_variant_id
    and variant.is_primary;

  if target_trip_id is null then
    raise exception 'Day and primary Route A must belong to the same trip'
      using errcode = '22023';
  end if;

  if not public.is_trip_owner(target_trip_id) then
    raise exception 'Trip owner access required' using errcode = '42501';
  end if;

  if submitted_count not between 2 and 20 then
    raise exception 'A day route requires between 2 and 20 stop references'
      using errcode = '22023';
  end if;

  if mode_count <> submitted_count - 1 then
    raise exception 'Leg mode count must equal stop count minus one'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(coalesce(ordered_item_ids, '{}'::uuid[])) with ordinality submitted(item_id, position)
    left join public.itinerary_items item on item.id = submitted.item_id
    left join public.places place on place.id = item.place_id
    where item.id is null
      or item.trip_id is distinct from target_trip_id
      or item.variant_id is distinct from target_variant_id
      or item.day_id is distinct from target_day_id
      or item.type not in ('activity', 'meal', 'hotel')
      or place.id is null
      or place.trip_id is distinct from target_trip_id
      or place.latitude is null
      or place.longitude is null
      or place.latitude not between -90 and 90
      or place.longitude not between -180 and 180
  ) then
    raise exception 'Every route stop must be an Activity, Meal, or Hotel from this day with saved coordinates'
      using errcode = '22023';
  end if;

  select count(*) into duplicate_group_count
  from (
    select submitted.item_id
    from unnest(ordered_item_ids) submitted(item_id)
    group by submitted.item_id
    having count(*) > 1
  ) duplicate_groups;

  select count(*) into invalid_duplicate_count
  from (
    select
      submitted.item_id,
      count(*) as occurrence_count,
      min(submitted.position) as first_position,
      max(submitted.position) as final_position
    from unnest(ordered_item_ids) with ordinality submitted(item_id, position)
    group by submitted.item_id
    having count(*) > 1
  ) duplicate
  join public.itinerary_items item on item.id = duplicate.item_id
  where duplicate.occurrence_count <> 2
    or item.type <> 'hotel'
    or duplicate.first_position <> 1
    or duplicate.final_position <> submitted_count;

  if duplicate_group_count > 1 or invalid_duplicate_count > 0 then
    raise exception 'Only one Hotel may repeat, exactly at the first and final positions'
      using errcode = '22023';
  end if;

  select count(distinct (place.latitude, place.longitude)) into distinct_location_count
  from unnest(ordered_item_ids) submitted(item_id)
  join public.itinerary_items item on item.id = submitted.item_id
  join public.places place on place.id = item.place_id;

  if distinct_location_count < 2 then
    raise exception 'A day route requires at least two distinct coordinate locations'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(coalesce(requested_leg_modes, '{}'::text[])) requested(mode)
    where requested.mode is null
      or requested.mode not in (
        'walk',
        'self_driving',
        'taxi',
        'rideshare',
        'bus',
        'subway',
        'tram',
        'shuttle',
        'train',
        'bike',
        'flight',
        'ferry',
        'cable_car',
        'motorcycle',
        'other'
      )
  ) then
    raise exception 'Invalid route leg mode' using errcode = '22023';
  end if;

  insert into public.day_route_plans (trip_id, variant_id, day_id)
  values (target_trip_id, target_variant_id, target_day_id)
  on conflict (day_id, variant_id)
  do update set updated_at = now()
  returning id into saved_plan_id;

  delete from public.day_route_legs where plan_id = saved_plan_id;
  delete from public.day_route_stops where plan_id = saved_plan_id;

  insert into public.day_route_stops (plan_id, item_id, position)
  select saved_plan_id, submitted.item_id, submitted.position::integer
  from unnest(ordered_item_ids) with ordinality submitted(item_id, position);

  insert into public.day_route_legs (
    plan_id,
    position,
    from_stop_id,
    to_stop_id,
    mode
  )
  select
    saved_plan_id,
    requested.position::integer,
    from_stop.id,
    to_stop.id,
    requested.mode
  from unnest(requested_leg_modes) with ordinality requested(mode, position)
  join public.day_route_stops from_stop
    on from_stop.plan_id = saved_plan_id
   and from_stop.position = requested.position
  join public.day_route_stops to_stop
    on to_stop.plan_id = saved_plan_id
   and to_stop.position = requested.position + 1;

  return saved_plan_id;
end;
$$;

create function public.save_day_route_calculation(
  target_plan_id uuid,
  calculated_config_signature text,
  normalized_calculated_legs jsonb,
  calculated_total_distance_meters integer,
  calculated_total_duration_seconds integer,
  calculated_provider_schema_version text default 'routes-v1'
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_trip_id uuid;
  expected_leg_count integer;
begin
  if app_private.app_current_user_id() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select trip_id into target_trip_id
  from public.day_route_plans
  where id = target_plan_id;

  if target_trip_id is null or not public.is_trip_owner(target_trip_id) then
    raise exception 'Trip owner access required' using errcode = '42501';
  end if;

  select count(*) into expected_leg_count
  from public.day_route_legs
  where plan_id = target_plan_id;

  if calculated_config_signature is null
    or char_length(calculated_config_signature) not between 1 and 256
    or normalized_calculated_legs is null
    or jsonb_typeof(normalized_calculated_legs) <> 'array'
    or jsonb_array_length(normalized_calculated_legs) <> expected_leg_count
    or calculated_total_distance_meters is null
    or calculated_total_distance_meters < 0
    or calculated_total_duration_seconds < 0
    or calculated_provider_schema_version is null
    or char_length(calculated_provider_schema_version) not between 1 and 80
  then
    raise exception 'Invalid route calculation snapshot' using errcode = '22023';
  end if;

  insert into public.day_route_calculations (
    plan_id,
    config_signature,
    calculated_legs,
    total_distance_meters,
    total_duration_seconds,
    provider_schema_version,
    computed_at
  ) values (
    target_plan_id,
    calculated_config_signature,
    normalized_calculated_legs,
    calculated_total_distance_meters,
    calculated_total_duration_seconds,
    calculated_provider_schema_version,
    now()
  )
  on conflict (plan_id)
  do update set
    config_signature = excluded.config_signature,
    calculated_legs = excluded.calculated_legs,
    total_distance_meters = excluded.total_distance_meters,
    total_duration_seconds = excluded.total_duration_seconds,
    provider_schema_version = excluded.provider_schema_version,
    computed_at = excluded.computed_at;
end;
$$;

create function public.clear_day_route_plan(
  target_day_id uuid,
  target_variant_id uuid
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_trip_id uuid;
begin
  if app_private.app_current_user_id() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select variant.trip_id into target_trip_id
  from public.trip_days day
  join public.route_variants variant on variant.id = day.variant_id
  where day.id = target_day_id
    and day.variant_id = target_variant_id
    and variant.is_primary;

  if target_trip_id is null or not public.is_trip_owner(target_trip_id) then
    raise exception 'Trip owner access required' using errcode = '42501';
  end if;

  delete from public.day_route_plans
  where day_id = target_day_id
    and variant_id = target_variant_id;
end;
$$;

-- Source: supabase/migrations/20260802130920_harden_manual_day_route_plans.sql
-- Keep every composite foreign key covered and make the legacy function
-- privileges explicit under Supabase's opt-in Data API grant model.

create index day_route_plans_variant_trip_idx
  on public.day_route_plans (variant_id, trip_id);

create index day_route_legs_from_stop_plan_idx
  on public.day_route_legs (from_stop_id, plan_id);

create index day_route_legs_to_stop_plan_idx
  on public.day_route_legs (to_stop_id, plan_id);

-- Source: supabase/migrations/20260803173303_route_variant_foundation.sql
-- Phase 5A promotes route_variants from a hidden primary Route A record to a
-- complete, independently editable trip-plan branch. Lifecycle writes remain
-- database-owned so limits, primary invariants, and duplication are atomic.

create unique index route_variants_trip_name_ci_unique
  on public.route_variants (trip_id, lower(btrim(name)));

do $$
begin
  if exists (
    select trip.id
    from public.trips trip
    left join public.route_variants variant
      on variant.trip_id = trip.id
     and variant.is_primary
    group by trip.id
    having count(variant.id) <> 1
  ) then
    raise exception 'VARIANT_PRIMARY_REQUIRED' using errcode = '23514';
  end if;
end;
$$;

create function public.enforce_route_variant_limit()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  perform 1
  from public.trips
  where id = new.trip_id
  for update;

  if (
    select count(*)
    from public.route_variants
    where trip_id = new.trip_id
  ) >= 3 then
    raise exception 'VARIANT_LIMIT_REACHED' using errcode = '22023';
  end if;

  return new;
end;
$$;

create trigger route_variants_max_three
before insert on public.route_variants
for each row execute function public.enforce_route_variant_limit();

create function public.enforce_route_variant_primary()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  affected_trip_id uuid;
begin
  affected_trip_id := case when tg_op = 'DELETE' then old.trip_id else new.trip_id end;

  if exists (select 1 from public.trips where id = affected_trip_id)
    and (
      select count(*)
      from public.route_variants
      where trip_id = affected_trip_id
        and is_primary
    ) <> 1
  then
    raise exception 'VARIANT_PRIMARY_REQUIRED' using errcode = '23514';
  end if;

  if tg_op = 'UPDATE'
    and old.trip_id is distinct from new.trip_id
    and exists (select 1 from public.trips where id = old.trip_id)
    and (
      select count(*)
      from public.route_variants
      where trip_id = old.trip_id
        and is_primary
    ) <> 1
  then
    raise exception 'VARIANT_PRIMARY_REQUIRED' using errcode = '23514';
  end if;

  return null;
end;
$$;

create constraint trigger route_variants_primary_after_insert
after insert on public.route_variants
deferrable initially deferred
for each row execute function public.enforce_route_variant_primary();

create constraint trigger route_variants_primary_after_update
after update on public.route_variants
deferrable initially deferred
for each row execute function public.enforce_route_variant_primary();

create constraint trigger route_variants_primary_after_delete
after delete on public.route_variants
deferrable initially deferred
for each row execute function public.enforce_route_variant_primary();

create function public.create_route_variant(
  target_trip_id uuid,
  source_variant_id uuid,
  variant_name text,
  variant_color text
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  locked_trip_id uuid;
  new_variant_id uuid;
  normalized_name text := btrim(variant_name);
  normalized_color text := lower(variant_color);
  copied_day_count integer;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  select trip.id into locked_trip_id
  from public.trips trip
  where trip.id = target_trip_id
    and trip.owner_id = current_user_id
  for update;

  if locked_trip_id is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  if source_variant_id is null or not exists (
    select 1
    from public.route_variants source
    where source.id = source_variant_id
      and source.trip_id = target_trip_id
  ) then
    raise exception 'VARIANT_SOURCE_NOT_FOUND' using errcode = '22023';
  end if;

  if normalized_name is null or char_length(normalized_name) not between 1 and 80 then
    raise exception 'VARIANT_NAME_INVALID' using errcode = '22023';
  end if;

  if normalized_color is null or normalized_color !~ '^#[0-9a-f]{6}$' then
    raise exception 'VARIANT_COLOR_INVALID' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.route_variants variant
    where variant.trip_id = target_trip_id
      and lower(btrim(variant.name)) = lower(normalized_name)
  ) then
    raise exception 'VARIANT_NAME_TAKEN' using errcode = '23505';
  end if;

  if (select count(*) from public.route_variants where trip_id = target_trip_id) >= 3 then
    raise exception 'VARIANT_LIMIT_REACHED' using errcode = '22023';
  end if;

  insert into public.route_variants (trip_id, name, color, is_primary)
  values (target_trip_id, normalized_name, normalized_color, false)
  returning id into new_variant_id;

  insert into public.trip_days (variant_id, day_number, date, title, notes)
  select new_variant_id, source.day_number, source.date, null, null
  from public.trip_days source
  where source.variant_id = source_variant_id
  order by source.day_number;

  get diagnostics copied_day_count = row_count;
  if copied_day_count = 0 then
    raise exception 'VARIANT_SOURCE_HAS_NO_DAYS' using errcode = '22023';
  end if;

  return new_variant_id;
end;
$$;

create function public.duplicate_route_variant(
  target_trip_id uuid,
  source_variant_id uuid,
  variant_name text,
  variant_color text
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  locked_trip_id uuid;
  normalized_name text := btrim(variant_name);
  normalized_color text := lower(variant_color);
  new_variant_id uuid;
  new_day_id uuid;
  new_item_id uuid;
  new_plan_id uuid;
  new_stop_id uuid;
  mapped_day_id uuid;
  mapped_item_id uuid;
  mapped_from_stop_id uuid;
  mapped_to_stop_id uuid;
  day_id_map jsonb := '{}'::jsonb;
  item_id_map jsonb := '{}'::jsonb;
  plan_id_map jsonb := '{}'::jsonb;
  stop_id_map jsonb := '{}'::jsonb;
  source_day public.trip_days%rowtype;
  source_item public.itinerary_items%rowtype;
  source_plan public.day_route_plans%rowtype;
  source_stop public.day_route_stops%rowtype;
  source_leg public.day_route_legs%rowtype;
  copied_day_count integer := 0;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  select trip.id into locked_trip_id
  from public.trips trip
  where trip.id = target_trip_id
    and trip.owner_id = current_user_id
  for update;

  if locked_trip_id is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  if source_variant_id is null or not exists (
    select 1
    from public.route_variants source
    where source.id = source_variant_id
      and source.trip_id = target_trip_id
  ) then
    raise exception 'VARIANT_SOURCE_NOT_FOUND' using errcode = '22023';
  end if;

  if normalized_name is null or char_length(normalized_name) not between 1 and 80 then
    raise exception 'VARIANT_NAME_INVALID' using errcode = '22023';
  end if;

  if normalized_color is null or normalized_color !~ '^#[0-9a-f]{6}$' then
    raise exception 'VARIANT_COLOR_INVALID' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.route_variants variant
    where variant.trip_id = target_trip_id
      and lower(btrim(variant.name)) = lower(normalized_name)
  ) then
    raise exception 'VARIANT_NAME_TAKEN' using errcode = '23505';
  end if;

  if (select count(*) from public.route_variants where trip_id = target_trip_id) >= 3 then
    raise exception 'VARIANT_LIMIT_REACHED' using errcode = '22023';
  end if;

  insert into public.route_variants (trip_id, name, color, is_primary)
  values (target_trip_id, normalized_name, normalized_color, false)
  returning id into new_variant_id;

  for source_day in
    select *
    from public.trip_days
    where variant_id = source_variant_id
    order by day_number
  loop
    new_day_id := gen_random_uuid();
    insert into public.trip_days (id, variant_id, day_number, date, title, notes)
    values (
      new_day_id,
      new_variant_id,
      source_day.day_number,
      source_day.date,
      source_day.title,
      source_day.notes
    );
    day_id_map := day_id_map || jsonb_build_object(source_day.id::text, new_day_id::text);
    copied_day_count := copied_day_count + 1;
  end loop;

  if copied_day_count = 0 then
    raise exception 'VARIANT_SOURCE_HAS_NO_DAYS' using errcode = '22023';
  end if;

  for source_item in
    select *
    from public.itinerary_items
    where trip_id = target_trip_id
      and variant_id = source_variant_id
    order by day_id, sort_order, id
  loop
    mapped_day_id := (day_id_map ->> source_item.day_id::text)::uuid;
    if mapped_day_id is null then
      raise exception 'VARIANT_DUPLICATION_MAPPING_FAILED' using errcode = 'P0001';
    end if;

    new_item_id := gen_random_uuid();
    insert into public.itinerary_items (
      id,
      trip_id,
      variant_id,
      day_id,
      type,
      title,
      start_time,
      end_time,
      place_id,
      notes,
      booking_url,
      details,
      sort_order,
      schedule_kind,
      schedule_text
    ) values (
      new_item_id,
      target_trip_id,
      new_variant_id,
      mapped_day_id,
      source_item.type,
      source_item.title,
      source_item.start_time,
      source_item.end_time,
      source_item.place_id,
      source_item.notes,
      source_item.booking_url,
      source_item.details,
      source_item.sort_order,
      source_item.schedule_kind,
      source_item.schedule_text
    );
    item_id_map := item_id_map || jsonb_build_object(source_item.id::text, new_item_id::text);

    insert into public.itinerary_item_links (id, item_id, label, url, sort_order)
    select gen_random_uuid(), new_item_id, link.label, link.url, link.sort_order
    from public.itinerary_item_links link
    where link.item_id = source_item.id
    order by link.sort_order, link.id;
  end loop;

  for source_plan in
    select *
    from public.day_route_plans
    where trip_id = target_trip_id
      and variant_id = source_variant_id
    order by day_id, id
  loop
    mapped_day_id := (day_id_map ->> source_plan.day_id::text)::uuid;
    if mapped_day_id is null then
      raise exception 'VARIANT_DUPLICATION_MAPPING_FAILED' using errcode = 'P0001';
    end if;

    new_plan_id := gen_random_uuid();
    insert into public.day_route_plans (id, trip_id, variant_id, day_id)
    values (new_plan_id, target_trip_id, new_variant_id, mapped_day_id);
    plan_id_map := plan_id_map || jsonb_build_object(source_plan.id::text, new_plan_id::text);

    for source_stop in
      select *
      from public.day_route_stops
      where plan_id = source_plan.id
      order by position, id
    loop
      mapped_item_id := (item_id_map ->> source_stop.item_id::text)::uuid;
      if mapped_item_id is null then
        raise exception 'VARIANT_DUPLICATION_MAPPING_FAILED' using errcode = 'P0001';
      end if;

      new_stop_id := gen_random_uuid();
      insert into public.day_route_stops (id, plan_id, item_id, position)
      values (new_stop_id, new_plan_id, mapped_item_id, source_stop.position);
      stop_id_map := stop_id_map || jsonb_build_object(source_stop.id::text, new_stop_id::text);
    end loop;

    for source_leg in
      select *
      from public.day_route_legs
      where plan_id = source_plan.id
      order by position, id
    loop
      mapped_from_stop_id := (stop_id_map ->> source_leg.from_stop_id::text)::uuid;
      mapped_to_stop_id := (stop_id_map ->> source_leg.to_stop_id::text)::uuid;
      if mapped_from_stop_id is null or mapped_to_stop_id is null then
        raise exception 'VARIANT_DUPLICATION_MAPPING_FAILED' using errcode = 'P0001';
      end if;

      insert into public.day_route_legs (
        id,
        plan_id,
        position,
        from_stop_id,
        to_stop_id,
        mode
      ) values (
        gen_random_uuid(),
        new_plan_id,
        source_leg.position,
        mapped_from_stop_id,
        mapped_to_stop_id,
        source_leg.mode
      );
    end loop;
  end loop;

  -- day_route_calculations are intentionally not copied. The new saved route
  -- retains desired stops and leg modes but requires an explicit calculation.
  return new_variant_id;
end;
$$;

create function public.update_route_variant_metadata(
  target_trip_id uuid,
  target_variant_id uuid,
  variant_name text,
  variant_color text
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  locked_trip_id uuid;
  normalized_name text := btrim(variant_name);
  normalized_color text := lower(variant_color);
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  select trip.id into locked_trip_id
  from public.trips trip
  where trip.id = target_trip_id
    and trip.owner_id = current_user_id
  for update;

  if locked_trip_id is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.route_variants variant
    where variant.id = target_variant_id
      and variant.trip_id = target_trip_id
  ) then
    raise exception 'VARIANT_NOT_FOUND' using errcode = '22023';
  end if;

  if normalized_name is null or char_length(normalized_name) not between 1 and 80 then
    raise exception 'VARIANT_NAME_INVALID' using errcode = '22023';
  end if;

  if normalized_color is null or normalized_color !~ '^#[0-9a-f]{6}$' then
    raise exception 'VARIANT_COLOR_INVALID' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.route_variants variant
    where variant.trip_id = target_trip_id
      and variant.id <> target_variant_id
      and lower(btrim(variant.name)) = lower(normalized_name)
  ) then
    raise exception 'VARIANT_NAME_TAKEN' using errcode = '23505';
  end if;

  update public.route_variants
  set name = normalized_name,
      color = normalized_color
  where id = target_variant_id
    and trip_id = target_trip_id;

  return target_variant_id;
end;
$$;

create function public.set_primary_route_variant(
  target_trip_id uuid,
  target_variant_id uuid
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  locked_trip_id uuid;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  select trip.id into locked_trip_id
  from public.trips trip
  where trip.id = target_trip_id
    and trip.owner_id = current_user_id
  for update;

  if locked_trip_id is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.route_variants variant
    where variant.id = target_variant_id
      and variant.trip_id = target_trip_id
  ) then
    raise exception 'VARIANT_NOT_FOUND' using errcode = '22023';
  end if;

  update public.route_variants
  set is_primary = false
  where trip_id = target_trip_id
    and is_primary;

  update public.route_variants
  set is_primary = true
  where id = target_variant_id
    and trip_id = target_trip_id;

  return target_variant_id;
end;
$$;

create function public.delete_route_variant(
  target_trip_id uuid,
  target_variant_id uuid
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  locked_trip_id uuid;
  target_is_primary boolean;
  variant_count integer;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  select trip.id into locked_trip_id
  from public.trips trip
  where trip.id = target_trip_id
    and trip.owner_id = current_user_id
  for update;

  if locked_trip_id is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  select variant.is_primary into target_is_primary
  from public.route_variants variant
  where variant.id = target_variant_id
    and variant.trip_id = target_trip_id;

  if target_is_primary is null then
    raise exception 'VARIANT_NOT_FOUND' using errcode = '22023';
  end if;

  select count(*) into variant_count
  from public.route_variants
  where trip_id = target_trip_id;

  if variant_count <= 1 then
    raise exception 'VARIANT_FINAL_DELETE_FORBIDDEN' using errcode = '22023';
  end if;

  if target_is_primary then
    raise exception 'VARIANT_PRIMARY_DELETE_FORBIDDEN' using errcode = '22023';
  end if;

  delete from public.route_variants
  where id = target_variant_id
    and trip_id = target_trip_id;

  return target_variant_id;
end;
$$;

create function public.insert_variant_day(
  target_trip_id uuid,
  target_variant_id uuid,
  before_day_number integer
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  locked_trip_id uuid;
  new_day_id uuid;
  current_count integer;
  current_start date;
  dates_complete boolean;
  target_is_primary boolean;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  select trip.id into locked_trip_id
  from public.trips trip
  where trip.id = target_trip_id
    and trip.owner_id = current_user_id
  for update;

  if locked_trip_id is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  select variant.is_primary into target_is_primary
  from public.route_variants variant
  where variant.id = target_variant_id
    and variant.trip_id = target_trip_id;

  if target_is_primary is null then
    raise exception 'VARIANT_NOT_FOUND' using errcode = '22023';
  end if;

  select count(*), min(date), count(date) = count(*)
  into current_count, current_start, dates_complete
  from public.trip_days
  where variant_id = target_variant_id;

  if current_count >= 366 then
    raise exception 'Trips cannot contain more than 366 days' using errcode = '22023';
  end if;
  if before_day_number not between 1 and current_count + 1 then
    raise exception 'Invalid day position' using errcode = '22023';
  end if;

  update public.trip_days set date = null where variant_id = target_variant_id;
  update public.trip_days set day_number = day_number + 1000 where variant_id = target_variant_id;
  update public.trip_days
  set day_number = case
    when day_number - 1000 >= before_day_number then day_number - 999
    else day_number - 1000
  end
  where variant_id = target_variant_id;

  insert into public.trip_days (variant_id, day_number, date)
  values (target_variant_id, before_day_number, null)
  returning id into new_day_id;

  if dates_complete and before_day_number = 1 then
    current_start := current_start - 1;
  end if;

  update public.trip_days
  set date = case when dates_complete then current_start + (day_number - 1) else null end
  where variant_id = target_variant_id;

  if target_is_primary then
    update public.trips
    set start_date = case when dates_complete then current_start else null end,
        end_date = case when dates_complete then current_start + current_count else null end,
        day_count = current_count + 1
    where id = target_trip_id;
  end if;

  return new_day_id;
end;
$$;

create function public.remove_variant_day(
  target_trip_id uuid,
  target_variant_id uuid,
  target_day_id uuid
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  locked_trip_id uuid;
  removed_number integer;
  current_count integer;
  current_start date;
  dates_complete boolean;
  target_is_primary boolean;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  select trip.id into locked_trip_id
  from public.trips trip
  where trip.id = target_trip_id
    and trip.owner_id = current_user_id
  for update;

  if locked_trip_id is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  select variant.is_primary into target_is_primary
  from public.route_variants variant
  where variant.id = target_variant_id
    and variant.trip_id = target_trip_id;

  if target_is_primary is null then
    raise exception 'VARIANT_NOT_FOUND' using errcode = '22023';
  end if;

  select count(*), min(date), count(date) = count(*)
  into current_count, current_start, dates_complete
  from public.trip_days
  where variant_id = target_variant_id;

  if current_count <= 1 then
    raise exception 'A route variant must keep at least one day' using errcode = '22023';
  end if;

  select day_number into removed_number
  from public.trip_days
  where id = target_day_id
    and variant_id = target_variant_id;

  if removed_number is null then
    raise exception 'Day not found' using errcode = '22023';
  end if;

  delete from public.trip_days
  where id = target_day_id
    and variant_id = target_variant_id;

  update public.trip_days set date = null where variant_id = target_variant_id;
  update public.trip_days set day_number = day_number + 1000 where variant_id = target_variant_id;
  update public.trip_days
  set day_number = day_number - 1000 - case
    when day_number - 1000 > removed_number then 1
    else 0
  end
  where variant_id = target_variant_id;

  if dates_complete and removed_number = 1 then
    current_start := current_start + 1;
  end if;

  update public.trip_days
  set date = case when dates_complete then current_start + (day_number - 1) else null end
  where variant_id = target_variant_id;

  if target_is_primary then
    update public.trips
    set start_date = case when dates_complete then current_start else null end,
        end_date = case when dates_complete then current_start + current_count - 2 else null end,
        day_count = current_count - 1
    where id = target_trip_id;
  end if;

  return target_day_id;
end;
$$;

create or replace function public.save_day_route_plan(
  target_day_id uuid,
  target_variant_id uuid,
  ordered_item_ids uuid[],
  requested_leg_modes text[]
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_trip_id uuid;
  saved_plan_id uuid;
  submitted_count integer := coalesce(cardinality(ordered_item_ids), 0);
  mode_count integer := coalesce(cardinality(requested_leg_modes), 0);
  duplicate_group_count integer;
  invalid_duplicate_count integer;
  distinct_location_count integer;
begin
  if app_private.app_current_user_id() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select variant.trip_id into target_trip_id
  from public.trip_days day
  join public.route_variants variant on variant.id = day.variant_id
  where day.id = target_day_id
    and day.variant_id = target_variant_id;

  if target_trip_id is null then
    raise exception 'Day and route variant must belong to the same trip'
      using errcode = '22023';
  end if;

  if not public.is_trip_owner(target_trip_id) then
    raise exception 'Trip owner access required' using errcode = '42501';
  end if;

  if submitted_count not between 2 and 20 then
    raise exception 'A day route requires between 2 and 20 stop references'
      using errcode = '22023';
  end if;

  if mode_count <> submitted_count - 1 then
    raise exception 'Leg mode count must equal stop count minus one'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(coalesce(ordered_item_ids, '{}'::uuid[])) with ordinality submitted(item_id, position)
    left join public.itinerary_items item on item.id = submitted.item_id
    left join public.places place on place.id = item.place_id
    where item.id is null
      or item.trip_id is distinct from target_trip_id
      or item.variant_id is distinct from target_variant_id
      or item.day_id is distinct from target_day_id
      or item.type not in ('activity', 'meal', 'hotel')
      or place.id is null
      or place.trip_id is distinct from target_trip_id
      or place.latitude is null
      or place.longitude is null
      or place.latitude not between -90 and 90
      or place.longitude not between -180 and 180
  ) then
    raise exception 'Every route stop must be an Activity, Meal, or Hotel from this day with saved coordinates'
      using errcode = '22023';
  end if;

  select count(*) into duplicate_group_count
  from (
    select submitted.item_id
    from unnest(ordered_item_ids) submitted(item_id)
    group by submitted.item_id
    having count(*) > 1
  ) duplicate_groups;

  select count(*) into invalid_duplicate_count
  from (
    select
      submitted.item_id,
      count(*) as occurrence_count,
      min(submitted.position) as first_position,
      max(submitted.position) as final_position
    from unnest(ordered_item_ids) with ordinality submitted(item_id, position)
    group by submitted.item_id
    having count(*) > 1
  ) duplicate
  join public.itinerary_items item on item.id = duplicate.item_id
  where duplicate.occurrence_count <> 2
    or item.type <> 'hotel'
    or duplicate.first_position <> 1
    or duplicate.final_position <> submitted_count;

  if duplicate_group_count > 1 or invalid_duplicate_count > 0 then
    raise exception 'Only one Hotel may repeat, exactly at the first and final positions'
      using errcode = '22023';
  end if;

  select count(distinct (place.latitude, place.longitude)) into distinct_location_count
  from unnest(ordered_item_ids) submitted(item_id)
  join public.itinerary_items item on item.id = submitted.item_id
  join public.places place on place.id = item.place_id;

  if distinct_location_count < 2 then
    raise exception 'A day route requires at least two distinct coordinate locations'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(coalesce(requested_leg_modes, '{}'::text[])) requested(mode)
    where requested.mode is null
      or requested.mode not in (
        'walk',
        'self_driving',
        'taxi',
        'rideshare',
        'bus',
        'subway',
        'tram',
        'shuttle',
        'train',
        'bike',
        'flight',
        'ferry',
        'cable_car',
        'motorcycle',
        'other'
      )
  ) then
    raise exception 'Invalid route leg mode' using errcode = '22023';
  end if;

  insert into public.day_route_plans (trip_id, variant_id, day_id)
  values (target_trip_id, target_variant_id, target_day_id)
  on conflict (day_id, variant_id)
  do update set updated_at = now()
  returning id into saved_plan_id;

  delete from public.day_route_legs where plan_id = saved_plan_id;
  delete from public.day_route_stops where plan_id = saved_plan_id;

  insert into public.day_route_stops (plan_id, item_id, position)
  select saved_plan_id, submitted.item_id, submitted.position::integer
  from unnest(ordered_item_ids) with ordinality submitted(item_id, position);

  insert into public.day_route_legs (
    plan_id,
    position,
    from_stop_id,
    to_stop_id,
    mode
  )
  select
    saved_plan_id,
    requested.position::integer,
    from_stop.id,
    to_stop.id,
    requested.mode
  from unnest(requested_leg_modes) with ordinality requested(mode, position)
  join public.day_route_stops from_stop
    on from_stop.plan_id = saved_plan_id
   and from_stop.position = requested.position
  join public.day_route_stops to_stop
    on to_stop.plan_id = saved_plan_id
   and to_stop.position = requested.position + 1;

  return saved_plan_id;
end;
$$;

create or replace function public.clear_day_route_plan(
  target_day_id uuid,
  target_variant_id uuid
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_trip_id uuid;
begin
  if app_private.app_current_user_id() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select variant.trip_id into target_trip_id
  from public.trip_days day
  join public.route_variants variant on variant.id = day.variant_id
  where day.id = target_day_id
    and day.variant_id = target_variant_id;

  if target_trip_id is null or not public.is_trip_owner(target_trip_id) then
    raise exception 'Trip owner access required' using errcode = '42501';
  end if;

  delete from public.day_route_plans
  where day_id = target_day_id
    and variant_id = target_variant_id;
end;
$$;

-- Source: supabase/migrations/20260803183257_allow_previous_day_hotel_route_start.sql
-- Day routes may begin at the immediately previous day's Hotel and end at the
-- active day's Hotel. All other route stops remain scoped to the active day.

create or replace function public.save_day_route_plan(
  target_day_id uuid,
  target_variant_id uuid,
  ordered_item_ids uuid[],
  requested_leg_modes text[]
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_trip_id uuid;
  previous_day_id uuid;
  saved_plan_id uuid;
  submitted_count integer := coalesce(cardinality(ordered_item_ids), 0);
  mode_count integer := coalesce(cardinality(requested_leg_modes), 0);
  duplicate_group_count integer;
  invalid_duplicate_count integer;
  distinct_location_count integer;
begin
  if app_private.app_current_user_id() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select
    variant.trip_id,
    previous_day.id
  into target_trip_id, previous_day_id
  from public.trip_days day
  join public.route_variants variant on variant.id = day.variant_id
  left join public.trip_days previous_day
    on previous_day.variant_id = day.variant_id
   and previous_day.day_number = day.day_number - 1
  where day.id = target_day_id
    and day.variant_id = target_variant_id;

  if target_trip_id is null then
    raise exception 'Day and route variant must belong to the same trip'
      using errcode = '22023';
  end if;

  if not public.is_trip_owner(target_trip_id) then
    raise exception 'Trip owner access required' using errcode = '42501';
  end if;

  if submitted_count not between 2 and 20 then
    raise exception 'A day route requires between 2 and 20 stop references'
      using errcode = '22023';
  end if;

  if mode_count <> submitted_count - 1 then
    raise exception 'Leg mode count must equal stop count minus one'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(coalesce(ordered_item_ids, '{}'::uuid[])) with ordinality submitted(item_id, position)
    left join public.itinerary_items item on item.id = submitted.item_id
    left join public.places place on place.id = item.place_id
    where item.id is null
      or item.trip_id is distinct from target_trip_id
      or item.variant_id is distinct from target_variant_id
      or (
        item.day_id is distinct from target_day_id
        and not (
          submitted.position = 1
          and previous_day_id is not null
          and item.day_id = previous_day_id
          and item.type = 'hotel'
        )
      )
      or item.type not in ('activity', 'meal', 'hotel')
      or place.id is null
      or place.trip_id is distinct from target_trip_id
      or place.latitude is null
      or place.longitude is null
      or place.latitude not between -90 and 90
      or place.longitude not between -180 and 180
  ) then
    raise exception 'Every route stop must be an eligible item from this day, except the first stop may be the previous day Hotel'
      using errcode = '22023';
  end if;

  select count(*) into duplicate_group_count
  from (
    select submitted.item_id
    from unnest(ordered_item_ids) submitted(item_id)
    group by submitted.item_id
    having count(*) > 1
  ) duplicate_groups;

  select count(*) into invalid_duplicate_count
  from (
    select
      submitted.item_id,
      count(*) as occurrence_count,
      min(submitted.position) as first_position,
      max(submitted.position) as final_position
    from unnest(ordered_item_ids) with ordinality submitted(item_id, position)
    group by submitted.item_id
    having count(*) > 1
  ) duplicate
  join public.itinerary_items item on item.id = duplicate.item_id
  where duplicate.occurrence_count <> 2
    or item.type <> 'hotel'
    or duplicate.first_position <> 1
    or duplicate.final_position <> submitted_count;

  if duplicate_group_count > 1 or invalid_duplicate_count > 0 then
    raise exception 'Only one Hotel may repeat, exactly at the first and final positions'
      using errcode = '22023';
  end if;

  select count(distinct (place.latitude, place.longitude)) into distinct_location_count
  from unnest(ordered_item_ids) submitted(item_id)
  join public.itinerary_items item on item.id = submitted.item_id
  join public.places place on place.id = item.place_id;

  if distinct_location_count < 2 then
    raise exception 'A day route requires at least two distinct coordinate locations'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(coalesce(requested_leg_modes, '{}'::text[])) requested(mode)
    where requested.mode is null
      or requested.mode not in (
        'walk',
        'self_driving',
        'taxi',
        'rideshare',
        'bus',
        'subway',
        'tram',
        'shuttle',
        'train',
        'bike',
        'flight',
        'ferry',
        'cable_car',
        'motorcycle',
        'other'
      )
  ) then
    raise exception 'Invalid route leg mode' using errcode = '22023';
  end if;

  insert into public.day_route_plans (trip_id, variant_id, day_id)
  values (target_trip_id, target_variant_id, target_day_id)
  on conflict (day_id, variant_id)
  do update set updated_at = now()
  returning id into saved_plan_id;

  delete from public.day_route_legs where plan_id = saved_plan_id;
  delete from public.day_route_stops where plan_id = saved_plan_id;

  insert into public.day_route_stops (plan_id, item_id, position)
  select saved_plan_id, submitted.item_id, submitted.position::integer
  from unnest(ordered_item_ids) with ordinality submitted(item_id, position);

  insert into public.day_route_legs (
    plan_id,
    position,
    from_stop_id,
    to_stop_id,
    mode
  )
  select
    saved_plan_id,
    requested.position::integer,
    from_stop.id,
    to_stop.id,
    requested.mode
  from unnest(requested_leg_modes) with ordinality requested(mode, position)
  join public.day_route_stops from_stop
    on from_stop.plan_id = saved_plan_id
   and from_stop.position = requested.position
  join public.day_route_stops to_stop
    on to_stop.plan_id = saved_plan_id
   and to_stop.position = requested.position + 1;

  return saved_plan_id;
end;
$$;

create function public.clear_route_variant_items(
  target_trip_id uuid,
  target_variant_id uuid,
  target_item_ids uuid[]
) returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  submitted_count integer := coalesce(cardinality(target_item_ids), 0);
  deleted_count integer;
  locked_trip_id uuid;
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select trip.id into locked_trip_id
  from public.trips trip
  where trip.id = target_trip_id
    and trip.owner_id = current_user_id
  for update;

  if locked_trip_id is null then
    raise exception 'Trip owner access required' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.route_variants variant
    where variant.id = target_variant_id
      and variant.trip_id = target_trip_id
  ) then
    raise exception 'The active route variant was not found' using errcode = '22023';
  end if;

  if submitted_count not between 1 and 2000
    or submitted_count <> (
      select count(distinct submitted.item_id)
      from unnest(coalesce(target_item_ids, '{}'::uuid[])) submitted(item_id)
    )
  then
    raise exception 'Select between 1 and 2000 unique itinerary items to clear'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(target_item_ids) submitted(item_id)
    left join public.itinerary_items item on item.id = submitted.item_id
    where item.id is null
      or item.trip_id is distinct from target_trip_id
      or item.variant_id is distinct from target_variant_id
  ) then
    raise exception 'Every selected item must belong to the active route variant'
      using errcode = '22023';
  end if;

  delete from public.itinerary_items item
  where item.id = any(target_item_ids)
    and item.trip_id = target_trip_id
    and item.variant_id = target_variant_id;

  get diagnostics deleted_count = row_count;
  if deleted_count <> submitted_count then
    raise exception 'The selected cells changed before they could be cleared'
      using errcode = '40001';
  end if;

  return deleted_count;
end;
$$;

-- Source: supabase/migrations/20260806125928_phase_6a_secure_public_sharing.sql
-- Phase 6A exposes one live, revocable capability link for one route variant.
-- Public callers receive only the explicit JSON projection assembled below;
-- planner tables and link-management rows remain inaccessible to anon.

create type public.public_itinerary_view as enum ('overview', 'table', 'timeline');

create table public.public_itinerary_links (
  id uuid primary key default gen_random_uuid(),
  public_token uuid not null default gen_random_uuid(),
  trip_id uuid not null references public.trips (id) on delete cascade,
  variant_id uuid not null,
  created_by varchar(64) not null,
  default_view public.public_itinerary_view not null default 'overview',
  show_times boolean not null default true,
  show_map_routes boolean not null default true,
  allow_route_explore boolean not null default true,
  show_addresses boolean not null default false,
  show_notes boolean not null default false,
  show_quick_action_links boolean not null default true,
  share_title text,
  share_description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  revoked_at timestamptz,
  constraint public_itinerary_links_token_unique unique (public_token),
  constraint public_itinerary_links_variant_trip_fkey foreign key (variant_id, trip_id)
    references public.route_variants (id, trip_id) on delete cascade,
  constraint public_itinerary_links_title_length check (
    share_title is null or char_length(btrim(share_title)) between 1 and 160
  ),
  constraint public_itinerary_links_description_length check (
    share_description is null or char_length(btrim(share_description)) between 1 and 500
  ),
  constraint public_itinerary_links_revoke_order check (
    revoked_at is null or revoked_at >= created_at
  )
);

create unique index public_itinerary_links_one_active_variant_idx
  on public.public_itinerary_links (variant_id)
  where revoked_at is null;

create index public_itinerary_links_trip_idx
  on public.public_itinerary_links (trip_id, variant_id);

create function public.enforce_public_itinerary_link_owner()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not exists (
    select 1
    from public.trips trip
    where trip.id = new.trip_id
      and trip.owner_id = new.created_by
  ) then
    raise exception 'PUBLIC_LINK_OWNER_MISMATCH' using errcode = '23514';
  end if;

  return new;
end;
$$;

create trigger public_itinerary_links_enforce_owner
before insert or update of trip_id, variant_id, created_by
on public.public_itinerary_links
for each row execute function public.enforce_public_itinerary_link_owner();

create trigger public_itinerary_links_set_updated_at
before update on public.public_itinerary_links
for each row execute function public.set_updated_at();

alter table public.public_itinerary_links enable row level security;

create function public.create_public_itinerary_link(
  target_variant_id uuid,
  requested_default_view public.public_itinerary_view default 'overview',
  requested_show_times boolean default true,
  requested_show_map_routes boolean default true,
  requested_allow_route_explore boolean default true,
  requested_show_addresses boolean default false,
  requested_show_notes boolean default false,
  requested_show_quick_action_links boolean default true,
  requested_share_title text default null,
  requested_share_description text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  target_trip_id uuid;
  created_link public.public_itinerary_links%rowtype;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  select variant.trip_id into target_trip_id
  from public.route_variants variant
  join public.trips trip on trip.id = variant.trip_id
  where variant.id = target_variant_id
    and trip.owner_id = current_user_id
  for update of variant;

  if target_trip_id is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.public_itinerary_links link
    where link.variant_id = target_variant_id
      and link.revoked_at is null
  ) then
    raise exception 'PUBLIC_LINK_ACTIVE_EXISTS' using errcode = '23505';
  end if;

  insert into public.public_itinerary_links (
    trip_id,
    variant_id,
    created_by,
    default_view,
    show_times,
    show_map_routes,
    allow_route_explore,
    show_addresses,
    show_notes,
    show_quick_action_links,
    share_title,
    share_description
  ) values (
    target_trip_id,
    target_variant_id,
    current_user_id,
    requested_default_view,
    requested_show_times,
    requested_show_map_routes,
    requested_allow_route_explore,
    requested_show_addresses,
    requested_show_notes,
    requested_show_quick_action_links,
    nullif(btrim(requested_share_title), ''),
    nullif(btrim(requested_share_description), '')
  ) returning * into created_link;

  return jsonb_build_object(
    'id', created_link.id,
    'publicToken', created_link.public_token,
    'tripId', created_link.trip_id,
    'variantId', created_link.variant_id,
    'defaultView', created_link.default_view,
    'showTimes', created_link.show_times,
    'showMapRoutes', created_link.show_map_routes,
    'allowRouteExplore', created_link.allow_route_explore,
    'showAddresses', created_link.show_addresses,
    'showNotes', created_link.show_notes,
    'showQuickActionLinks', created_link.show_quick_action_links,
    'shareTitle', created_link.share_title,
    'shareDescription', created_link.share_description,
    'createdAt', created_link.created_at,
    'updatedAt', created_link.updated_at
  );
end;
$$;

create function public.update_public_itinerary_link(
  target_link_id uuid,
  requested_default_view public.public_itinerary_view,
  requested_show_times boolean,
  requested_show_map_routes boolean,
  requested_allow_route_explore boolean,
  requested_show_addresses boolean,
  requested_show_notes boolean,
  requested_show_quick_action_links boolean,
  requested_share_title text,
  requested_share_description text
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  updated_link public.public_itinerary_links%rowtype;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  update public.public_itinerary_links link
  set
    default_view = requested_default_view,
    show_times = requested_show_times,
    show_map_routes = requested_show_map_routes,
    allow_route_explore = requested_allow_route_explore,
    show_addresses = requested_show_addresses,
    show_notes = requested_show_notes,
    show_quick_action_links = requested_show_quick_action_links,
    share_title = nullif(btrim(requested_share_title), ''),
    share_description = nullif(btrim(requested_share_description), '')
  from public.trips trip
  where link.id = target_link_id
    and link.trip_id = trip.id
    and trip.owner_id = current_user_id
    and link.created_by = current_user_id
    and link.revoked_at is null
  returning link.* into updated_link;

  if updated_link.id is null then
    raise exception 'PUBLIC_LINK_OWNER_REQUIRED' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'id', updated_link.id,
    'publicToken', updated_link.public_token,
    'tripId', updated_link.trip_id,
    'variantId', updated_link.variant_id,
    'defaultView', updated_link.default_view,
    'showTimes', updated_link.show_times,
    'showMapRoutes', updated_link.show_map_routes,
    'allowRouteExplore', updated_link.allow_route_explore,
    'showAddresses', updated_link.show_addresses,
    'showNotes', updated_link.show_notes,
    'showQuickActionLinks', updated_link.show_quick_action_links,
    'shareTitle', updated_link.share_title,
    'shareDescription', updated_link.share_description,
    'createdAt', updated_link.created_at,
    'updatedAt', updated_link.updated_at
  );
end;
$$;

create function public.rotate_public_itinerary_link(target_link_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  rotated_link public.public_itinerary_links%rowtype;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  update public.public_itinerary_links link
  set public_token = gen_random_uuid()
  from public.trips trip
  where link.id = target_link_id
    and link.trip_id = trip.id
    and trip.owner_id = current_user_id
    and link.created_by = current_user_id
    and link.revoked_at is null
  returning link.* into rotated_link;

  if rotated_link.id is null then
    raise exception 'PUBLIC_LINK_OWNER_REQUIRED' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'id', rotated_link.id,
    'publicToken', rotated_link.public_token,
    'tripId', rotated_link.trip_id,
    'variantId', rotated_link.variant_id,
    'defaultView', rotated_link.default_view,
    'showTimes', rotated_link.show_times,
    'showMapRoutes', rotated_link.show_map_routes,
    'allowRouteExplore', rotated_link.allow_route_explore,
    'showAddresses', rotated_link.show_addresses,
    'showNotes', rotated_link.show_notes,
    'showQuickActionLinks', rotated_link.show_quick_action_links,
    'shareTitle', rotated_link.share_title,
    'shareDescription', rotated_link.share_description,
    'createdAt', rotated_link.created_at,
    'updatedAt', rotated_link.updated_at
  );
end;
$$;

create function public.revoke_public_itinerary_link(target_link_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  revoked_link_id uuid;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  update public.public_itinerary_links link
  set revoked_at = now()
  from public.trips trip
  where link.id = target_link_id
    and link.trip_id = trip.id
    and trip.owner_id = current_user_id
    and link.created_by = current_user_id
    and link.revoked_at is null
  returning link.id into revoked_link_id;

  if revoked_link_id is null then
    raise exception 'PUBLIC_LINK_OWNER_REQUIRED' using errcode = '42501';
  end if;
end;
$$;

create function public.list_public_itinerary_links(target_trip_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  result jsonb;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.trips trip
    where trip.id = target_trip_id
      and trip.owner_id = current_user_id
  ) then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', link.id,
        'publicToken', link.public_token,
        'tripId', link.trip_id,
        'variantId', link.variant_id,
        'defaultView', link.default_view,
        'showTimes', link.show_times,
        'showMapRoutes', link.show_map_routes,
        'allowRouteExplore', link.allow_route_explore,
        'showAddresses', link.show_addresses,
        'showNotes', link.show_notes,
        'showQuickActionLinks', link.show_quick_action_links,
        'shareTitle', link.share_title,
        'shareDescription', link.share_description,
        'createdAt', link.created_at,
        'updatedAt', link.updated_at
      ) order by link.created_at
    ),
    '[]'::jsonb
  ) into result
  from public.public_itinerary_links link
  where link.trip_id = target_trip_id
    and link.created_by = current_user_id
    and link.revoked_at is null;

  return result;
end;
$$;

create function public.get_public_itinerary(shared_token uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  shared record;
  city_sequence jsonb;
  cover_cities jsonb;
  city_summary text;
  days_projection jsonb;
  routes_projection jsonb;
begin
  select
    link.id as link_id,
    link.default_view,
    link.show_times,
    link.show_map_routes,
    link.allow_route_explore,
    link.show_addresses,
    link.show_notes,
    link.show_quick_action_links,
    link.share_title,
    link.share_description,
    trip.id as trip_id,
    trip.title as trip_title,
    trip.timezone,
    trip.start_date,
    trip.end_date,
    trip.day_count,
    variant.id as variant_id,
    variant.name as variant_name,
    variant.color as variant_color
  into shared
  from public.public_itinerary_links link
  join public.trips trip on trip.id = link.trip_id
  join public.route_variants variant
    on variant.id = link.variant_id
   and variant.trip_id = link.trip_id
  where link.public_token = shared_token
    and link.revoked_at is null;

  if shared.link_id is null then
    return jsonb_build_object('available', false);
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'ref', encode(extensions.digest(shared.link_id::text || ':city:' || item.id::text, 'sha256'), 'hex'),
          'dayNumber', day.day_number,
          'date', day.date,
          'name', coalesce(place.display_name, item.title),
          'latitude', case when shared.show_map_routes then place.latitude else null end,
          'longitude', case when shared.show_map_routes then place.longitude else null end
        )
      ) order by day.day_number, item.sort_order, item.id
    ),
    '[]'::jsonb
  ) into city_sequence
  from public.trip_days day
  join public.itinerary_items item
    on item.day_id = day.id
   and item.variant_id = day.variant_id
   and item.trip_id = shared.trip_id
   and item.type = 'location'
  left join public.places place
    on place.id = item.place_id
   and place.trip_id = shared.trip_id
  where day.variant_id = shared.variant_id;

  select
    coalesce(jsonb_agg(city.name order by city.first_day), '[]'::jsonb),
    string_agg(city.name, ' · ' order by city.first_day)
  into cover_cities, city_summary
  from (
    select min(day.day_number) as first_day, coalesce(place.display_name, item.title) as name
    from public.trip_days day
    join public.itinerary_items item
      on item.day_id = day.id
     and item.variant_id = day.variant_id
     and item.trip_id = shared.trip_id
     and item.type = 'location'
    left join public.places place
      on place.id = item.place_id
     and place.trip_id = shared.trip_id
    where day.variant_id = shared.variant_id
    group by coalesce(place.display_name, item.title)
    order by first_day
    limit 3
  ) city;

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'ref', encode(extensions.digest(shared.link_id::text || ':day:' || day.id::text, 'sha256'), 'hex'),
          'dayNumber', day.day_number,
          'date', day.date,
          'title', day.title,
          'city', (
            select coalesce(place.display_name, city_item.title)
            from public.itinerary_items city_item
            left join public.places place
              on place.id = city_item.place_id
             and place.trip_id = shared.trip_id
            where city_item.day_id = day.id
              and city_item.variant_id = shared.variant_id
              and city_item.type = 'location'
            order by city_item.sort_order, city_item.id
            limit 1
          ),
          'items', (
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'ref', encode(extensions.digest(shared.link_id::text || ':item:' || item.id::text, 'sha256'), 'hex'),
                  'type', item.type,
                  'title', item.title,
                  'sortOrder', item.sort_order
                )
                || case
                  when shared.show_times then jsonb_strip_nulls(
                    jsonb_build_object(
                      'startTime', item.start_time,
                      'endTime', item.end_time,
                      'scheduleLabel', case
                        when item.schedule_kind = 'all_day' then 'All day'
                        when item.schedule_kind in ('period', 'approximate') then item.schedule_text
                        else null
                      end
                    )
                  )
                  else '{}'::jsonb
                end
                || case
                  when place.id is not null then jsonb_build_object(
                    'place', jsonb_strip_nulls(
                      jsonb_build_object(
                        'displayName', coalesce(place.display_name, item.title),
                        'latitude', case when shared.show_map_routes then place.latitude else null end,
                        'longitude', case when shared.show_map_routes then place.longitude else null end
                      )
                      || case
                        when shared.show_addresses and place.formatted_address is not null
                          then jsonb_build_object('address', place.formatted_address)
                        else '{}'::jsonb
                      end
                    )
                  )
                  else '{}'::jsonb
                end
                || case
                  when shared.show_notes and item.notes is not null
                    then jsonb_build_object('notes', item.notes)
                  else '{}'::jsonb
                end
                || case
                  when shared.show_quick_action_links then (
                    select case
                      when count(*) = 0 then '{}'::jsonb
                      else jsonb_build_object(
                        'links', jsonb_agg(
                          jsonb_build_object('label', btrim(link.label), 'url', link.url)
                          order by link.sort_order, link.id
                        )
                      )
                    end
                    from public.itinerary_item_links link
                    where link.item_id = item.id
                      and link.url ~* '^https?://[^[:space:]]+$'
                  )
                  else '{}'::jsonb
                end
                order by item.sort_order, item.id
              ),
              '[]'::jsonb
            )
            from public.itinerary_items item
            left join public.places place
              on place.id = item.place_id
             and place.trip_id = shared.trip_id
            where item.day_id = day.id
              and item.variant_id = shared.variant_id
              and item.trip_id = shared.trip_id
              and (item.type <> 'note' or shared.show_notes)
          )
        )
        || case
          when shared.show_notes and day.notes is not null
            then jsonb_build_object('notes', day.notes)
          else '{}'::jsonb
        end
      ) order by day.day_number, day.id
    ),
    '[]'::jsonb
  ) into days_projection
  from public.trip_days day
  where day.variant_id = shared.variant_id;

  if shared.show_map_routes then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'ref', encode(extensions.digest(shared.link_id::text || ':route:' || plan.id::text, 'sha256'), 'hex'),
          'dayRef', encode(extensions.digest(shared.link_id::text || ':day:' || plan.day_id::text, 'sha256'), 'hex'),
          'dayNumber', day.day_number,
          'status', case when calculation.plan_id is null then 'saved' else 'calculated' end,
          'stops', (
            select coalesce(
              jsonb_agg(
                jsonb_strip_nulls(
                  jsonb_build_object(
                    'ref', encode(extensions.digest(shared.link_id::text || ':item:' || item.id::text, 'sha256'), 'hex'),
                    'position', stop.position,
                    'title', item.title,
                    'type', item.type,
                    'displayName', coalesce(place.display_name, item.title),
                    'latitude', place.latitude,
                    'longitude', place.longitude
                  )
                ) order by stop.position, stop.id
              ),
              '[]'::jsonb
            )
            from public.day_route_stops stop
            join public.itinerary_items item
              on item.id = stop.item_id
             and item.trip_id = shared.trip_id
             and item.variant_id = shared.variant_id
            join public.places place
              on place.id = item.place_id
             and place.trip_id = shared.trip_id
            where stop.plan_id = plan.id
          ),
          'legs', (
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'position', leg.position,
                  'mode', leg.mode
                )
                || case
                  when computed.entry is not null then jsonb_strip_nulls(
                    jsonb_build_object(
                      'distanceMeters', computed.entry -> 'distanceMeters',
                      'durationSeconds', computed.entry -> 'durationSeconds',
                      'geometry', case
                        when computed.entry -> 'geometry' ->> 'source' = 'google' then
                          jsonb_build_object(
                            'source', 'google',
                            'encodedPolyline', computed.entry -> 'geometry' -> 'encodedPolyline'
                          )
                        when computed.entry -> 'geometry' ->> 'source' = 'straight' then
                          jsonb_build_object(
                            'source', 'straight',
                            'origin', jsonb_build_object(
                              'latitude', computed.entry -> 'geometry' -> 'origin' -> 'latitude',
                              'longitude', computed.entry -> 'geometry' -> 'origin' -> 'longitude'
                            ),
                            'destination', jsonb_build_object(
                              'latitude', computed.entry -> 'geometry' -> 'destination' -> 'latitude',
                              'longitude', computed.entry -> 'geometry' -> 'destination' -> 'longitude'
                            )
                          )
                        else null
                      end
                    )
                  )
                  else '{}'::jsonb
                end
                order by leg.position, leg.id
              ),
              '[]'::jsonb
            )
            from public.day_route_legs leg
            left join lateral (
              select element.value as entry
              from jsonb_array_elements(
                coalesce(calculation.calculated_legs, '[]'::jsonb)
              ) as element(value)
              where element.value ->> 'position' = leg.position::text
              limit 1
            ) computed on true
            where leg.plan_id = plan.id
          ),
          'totalDistanceMeters', calculation.total_distance_meters,
          'totalDurationSeconds', calculation.total_duration_seconds
        ) order by day.day_number, plan.id
      ),
      '[]'::jsonb
    ) into routes_projection
    from public.day_route_plans plan
    join public.trip_days day
      on day.id = plan.day_id
     and day.variant_id = plan.variant_id
    left join public.day_route_calculations calculation on calculation.plan_id = plan.id
    where plan.trip_id = shared.trip_id
      and plan.variant_id = shared.variant_id;
  else
    routes_projection := '[]'::jsonb;
  end if;

  return jsonb_build_object(
    'available', true,
    'settings', jsonb_build_object(
      'defaultView', shared.default_view,
      'showTimes', shared.show_times,
      'showMapRoutes', shared.show_map_routes,
      'allowRouteExplore', shared.allow_route_explore,
      'showAddresses', shared.show_addresses,
      'showNotes', shared.show_notes,
      'showQuickActionLinks', shared.show_quick_action_links
    ),
    'metadata', jsonb_build_object(
      'title', coalesce(shared.share_title, shared.trip_title || ' · ' || shared.variant_name),
      'description', coalesce(
        shared.share_description,
        shared.day_count || '-day itinerary'
          || case when city_summary is null then '' else ' · ' || city_summary end
          || ' · View plans, tickets and routes'
      ),
      'coverCities', cover_cities
    ),
    'trip', jsonb_build_object(
      'title', shared.trip_title,
      'timezone', shared.timezone,
      'startDate', shared.start_date,
      'endDate', shared.end_date,
      'dayCount', shared.day_count
    ),
    'variant', jsonb_build_object(
      'name', shared.variant_name,
      'color', shared.variant_color
    ),
    'citySequence', city_sequence,
    'days', days_projection,
    'savedRoutes', routes_projection
  );
end;
$$;

-- Source: supabase/migrations/20260806194850_expose_public_car_rental_summary.sql
-- Extend the existing strict public projection with a purpose-built car-rental
-- summary. Company/action are safe itinerary labels; the stored address remains
-- governed by the existing show_addresses privacy setting.

