   and item.variant_id = day.variant_id
   and item.trip_id = shared.trip_id
   and item.type = 'location'
  left join public.places place
    on place.id = item.place_id
   and place.trip_id = shared.trip_id
  where day.variant_id = shared.variant_id;

  select
    coalesce(jsonb_agg(city.name order by city.first_day), '[]'::jsonb),
    string_agg(city.name, ' · ' order by city.first_day)
  into cover_cities, city_summary
  from (
    select min(day.day_number) as first_day, coalesce(place.display_name, item.title) as name
    from public.trip_days day
    join public.itinerary_items item
      on item.day_id = day.id
     and item.variant_id = day.variant_id
     and item.trip_id = shared.trip_id
     and item.type = 'location'
    left join public.places place
      on place.id = item.place_id
     and place.trip_id = shared.trip_id
    where day.variant_id = shared.variant_id
    group by coalesce(place.display_name, item.title)
    order by first_day
    limit 3
  ) city;

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'ref', encode(extensions.digest(shared.link_id::text || ':day:' || day.id::text, 'sha256'), 'hex'),
          'dayNumber', day.day_number,
          'date', day.date,
          'title', day.title,
          'city', (
            select coalesce(place.display_name, city_item.title)
            from public.itinerary_items city_item
            left join public.places place
              on place.id = city_item.place_id
             and place.trip_id = shared.trip_id
            where city_item.day_id = day.id
              and city_item.variant_id = shared.variant_id
              and city_item.type = 'location'
            order by city_item.sort_order, city_item.id
            limit 1
          ),
          'items', (
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'ref', encode(extensions.digest(shared.link_id::text || ':item:' || item.id::text, 'sha256'), 'hex'),
                  'type', item.type,
                  'title', item.title,
                  'sortOrder', item.sort_order
                )
                || case
                  when shared.show_times then jsonb_strip_nulls(
                    jsonb_build_object(
                      'startTime', item.start_time,
                      'endTime', item.end_time,
                      'scheduleLabel', case
                        when item.schedule_kind = 'all_day' then 'All day'
                        when item.schedule_kind in ('period', 'approximate') then item.schedule_text
                        else null
                      end
                    )
                  )
                  else '{}'::jsonb
                end
                || case
                  when item.type = 'car_rental' then jsonb_build_object(
                    'carRental', jsonb_strip_nulls(
                      jsonb_build_object(
                        'action', case
                          when item.details ->> 'action' in ('pickup', 'return')
                            then item.details ->> 'action'
                          else null
                        end,
                        'company', nullif(btrim(item.details ->> 'provider'), '')
                      )
                      || case
                        when shared.show_addresses then jsonb_strip_nulls(
                          jsonb_build_object(
                            'address', nullif(btrim(item.details ->> 'address'), '')
                          )
                        )
                        else '{}'::jsonb
                      end
                    )
                  )
                  else '{}'::jsonb
                end
                || case
                  when place.id is not null then jsonb_build_object(
                    'place', jsonb_strip_nulls(
                      jsonb_build_object(
                        'displayName', coalesce(place.display_name, item.title),
                        'latitude', case when shared.show_map_routes then place.latitude else null end,
                        'longitude', case when shared.show_map_routes then place.longitude else null end
                      )
                      || case
                        when shared.show_addresses and place.formatted_address is not null
                          then jsonb_build_object('address', place.formatted_address)
                        else '{}'::jsonb
                      end
                    )
                  )
                  else '{}'::jsonb
                end
                || case
                  when shared.show_notes and item.notes is not null
                    then jsonb_build_object('notes', item.notes)
                  else '{}'::jsonb
                end
                || case
                  when shared.show_quick_action_links then (
                    select case
                      when count(*) = 0 then '{}'::jsonb
                      else jsonb_build_object(
                        'links', jsonb_agg(
                          jsonb_build_object('label', btrim(link.label), 'url', link.url)
                          order by link.sort_order, link.id
                        )
                      )
                    end
                    from public.itinerary_item_links link
                    where link.item_id = item.id
                      and link.url ~* '^https?://[^[:space:]]+$'
                  )
                  else '{}'::jsonb
                end
                order by item.sort_order, item.id
              ),
              '[]'::jsonb
            )
            from public.itinerary_items item
            left join public.places place
              on place.id = item.place_id
             and place.trip_id = shared.trip_id
            where item.day_id = day.id
              and item.variant_id = shared.variant_id
              and item.trip_id = shared.trip_id
              and (item.type <> 'note' or shared.show_notes)
          )
        )
        || case
          when shared.show_notes and day.notes is not null
            then jsonb_build_object('notes', day.notes)
          else '{}'::jsonb
        end
      ) order by day.day_number, day.id
    ),
    '[]'::jsonb
  ) into days_projection
  from public.trip_days day
  where day.variant_id = shared.variant_id;

  if shared.show_map_routes then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'ref', encode(extensions.digest(shared.link_id::text || ':route:' || plan.id::text, 'sha256'), 'hex'),
          'dayRef', encode(extensions.digest(shared.link_id::text || ':day:' || plan.day_id::text, 'sha256'), 'hex'),
          'dayNumber', day.day_number,
          'status', case when calculation.plan_id is null then 'saved' else 'calculated' end,
          'stops', (
            select coalesce(
              jsonb_agg(
                jsonb_strip_nulls(
                  jsonb_build_object(
                    'ref', encode(extensions.digest(shared.link_id::text || ':item:' || item.id::text, 'sha256'), 'hex'),
                    'position', stop.position,
                    'title', item.title,
                    'type', item.type,
                    'displayName', coalesce(place.display_name, item.title),
                    'latitude', place.latitude,
                    'longitude', place.longitude
                  )
                ) order by stop.position, stop.id
              ),
              '[]'::jsonb
            )
            from public.day_route_stops stop
            join public.itinerary_items item
              on item.id = stop.item_id
             and item.trip_id = shared.trip_id
             and item.variant_id = shared.variant_id
            join public.places place
              on place.id = item.place_id
             and place.trip_id = shared.trip_id
            where stop.plan_id = plan.id
          ),
          'legs', (
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'position', leg.position,
                  'mode', leg.mode
                )
                || case
                  when computed.entry is not null then jsonb_strip_nulls(
                    jsonb_build_object(
                      'distanceMeters', computed.entry -> 'distanceMeters',
                      'durationSeconds', computed.entry -> 'durationSeconds',
                      'geometry', case
                        when computed.entry -> 'geometry' ->> 'source' = 'google' then
                          jsonb_build_object(
                            'source', 'google',
                            'encodedPolyline', computed.entry -> 'geometry' -> 'encodedPolyline'
                          )
                        when computed.entry -> 'geometry' ->> 'source' = 'straight' then
                          jsonb_build_object(
                            'source', 'straight',
                            'origin', jsonb_build_object(
                              'latitude', computed.entry -> 'geometry' -> 'origin' -> 'latitude',
                              'longitude', computed.entry -> 'geometry' -> 'origin' -> 'longitude'
                            ),
                            'destination', jsonb_build_object(
                              'latitude', computed.entry -> 'geometry' -> 'destination' -> 'latitude',
                              'longitude', computed.entry -> 'geometry' -> 'destination' -> 'longitude'
                            )
                          )
                        else null
                      end
                    )
                  )
                  else '{}'::jsonb
                end
                order by leg.position, leg.id
              ),
              '[]'::jsonb
            )
            from public.day_route_legs leg
            left join lateral (
              select element.value as entry
              from jsonb_array_elements(
                coalesce(calculation.calculated_legs, '[]'::jsonb)
              ) as element(value)
              where element.value ->> 'position' = leg.position::text
              limit 1
            ) computed on true
            where leg.plan_id = plan.id
          ),
          'totalDistanceMeters', calculation.total_distance_meters,
          'totalDurationSeconds', calculation.total_duration_seconds
        ) order by day.day_number, plan.id
      ),
      '[]'::jsonb
    ) into routes_projection
    from public.day_route_plans plan
    join public.trip_days day
      on day.id = plan.day_id
     and day.variant_id = plan.variant_id
    left join public.day_route_calculations calculation on calculation.plan_id = plan.id
    where plan.trip_id = shared.trip_id
      and plan.variant_id = shared.variant_id;
  else
    routes_projection := '[]'::jsonb;
  end if;

  return jsonb_build_object(
    'available', true,
    'settings', jsonb_build_object(
      'defaultView', shared.default_view,
      'showTimes', shared.show_times,
      'showMapRoutes', shared.show_map_routes,
      'allowRouteExplore', shared.allow_route_explore,
      'showAddresses', shared.show_addresses,
      'showNotes', shared.show_notes,
      'showQuickActionLinks', shared.show_quick_action_links
    ),
    'metadata', jsonb_build_object(
      'title', coalesce(shared.share_title, shared.trip_title || ' · ' || shared.variant_name),
      'description', coalesce(
        shared.share_description,
        shared.day_count || '-day itinerary'
          || case when city_summary is null then '' else ' · ' || city_summary end
          || ' · View plans, tickets and routes'
      ),
      'coverCities', cover_cities
    ),
    'trip', jsonb_build_object(
      'title', shared.trip_title,
      'timezone', shared.timezone,
      'startDate', shared.start_date,
      'endDate', shared.end_date,
      'dayCount', shared.day_count
    ),
    'variant', jsonb_build_object(
      'name', shared.variant_name,
      'color', shared.variant_color
    ),
    'citySequence', city_sequence,
    'days', days_projection,
    'savedRoutes', routes_projection
  );
end;
$$;

-- Source: supabase/migrations/20260807190815_activity_ssot_locality_backfill_and_day_order.sql
-- Phase 6A+ keeps itinerary items as the content source of truth.  Structured
-- locality stays on the existing trip-scoped Place snapshot; legacy City items
-- remain intact and are used only to backfill/fallback where no Activity place
-- locality exists yet.

alter table public.places
  add column locality_name text,
  add column locality_kind text,
  add column country_code text,
  add column administrative_area_name text,
  add column locality_source text;

alter table public.places
  add constraint places_locality_name_length check (
    locality_name is null or char_length(btrim(locality_name)) between 1 and 300
  ) not valid,
  add constraint places_locality_kind_allowed check (
    locality_kind is null or locality_kind in (
      'locality',
      'postal_town',
      'administrative_area_level_3',
      'administrative_area_level_2',
      'sublocality_level_1',
      'sublocality',
      'legacy_city'
    )
  ) not valid,
  add constraint places_country_code_format check (
    country_code is null or country_code ~ '^[A-Z]{2}$'
  ) not valid,
  add constraint places_administrative_area_name_length check (
    administrative_area_name is null
      or char_length(btrim(administrative_area_name)) between 1 and 300
  ) not valid,
  add constraint places_locality_source_allowed check (
    locality_source is null or locality_source in (
      'google_address_component',
      'legacy_city'
    )
  ) not valid,
  add constraint places_locality_consistency check (
    (locality_name is null and locality_kind is null and locality_source is null)
    or
    (locality_name is not null and locality_kind is not null and locality_source is not null)
  ) not valid;

-- A legacy City row explicitly identifies its attached Place as the Day's City.
-- Backfill only previously unresolved Place rows, prefer the existing provider
-- display name, and never overwrite future/provider locality truth.
update public.places place
set locality_name = coalesce(
      nullif(btrim(place.display_name), ''),
      legacy_city.fallback_name
    ),
    locality_kind = 'legacy_city',
    locality_source = 'legacy_city'
from (
  select
    item.place_id,
    min(btrim(item.title)) as fallback_name
  from public.itinerary_items item
  where item.type = 'location'
    and item.place_id is not null
  group by item.place_id
) legacy_city
where place.id = legacy_city.place_id
  and place.locality_name is null
  and coalesce(nullif(btrim(place.display_name), ''), legacy_city.fallback_name) is not null;

alter table public.places validate constraint places_locality_name_length;

alter table public.places validate constraint places_locality_kind_allowed;

alter table public.places validate constraint places_country_code_format;

alter table public.places validate constraint places_administrative_area_name_length;

alter table public.places validate constraint places_locality_source_allowed;

alter table public.places validate constraint places_locality_consistency;

-- Keep the original RPC callable by the currently deployed client.  The v2 RPC
-- is a backward-compatible opt-in that adds only the normalized locality chosen
-- from the already-selected Place's typed address components.
create function public.upsert_google_place_snapshot_v2(
  target_trip_id uuid,
  provider_place_id text,
  place_display_name text,
  place_formatted_address text,
  place_latitude double precision,
  place_longitude double precision,
  place_locality_name text default null,
  place_locality_kind text default null,
  place_country_code text default null,
  place_administrative_area_name text default null
) returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  persisted_place_id uuid;
  normalized_locality_name text := nullif(btrim(place_locality_name), '');
  normalized_locality_kind text := nullif(btrim(place_locality_kind), '');
  normalized_country_code text := upper(nullif(btrim(place_country_code), ''));
  normalized_administrative_area text := nullif(btrim(place_administrative_area_name), '');
begin
  if not public.is_trip_owner(target_trip_id) then
    raise exception 'Trip owner access required' using errcode = '42501';
  end if;

  if provider_place_id is null or btrim(provider_place_id) = ''
    or place_display_name is null
    or char_length(btrim(place_display_name)) not between 1 and 300
  then
    raise exception 'Valid Google place identity and display name are required'
      using errcode = '22023';
  end if;

  if (normalized_locality_name is null) <> (normalized_locality_kind is null)
    or normalized_locality_kind is not null and normalized_locality_kind not in (
      'locality',
      'postal_town',
      'administrative_area_level_3',
      'administrative_area_level_2',
      'sublocality_level_1',
      'sublocality'
    )
    or normalized_country_code is not null and normalized_country_code !~ '^[A-Z]{2}$'
  then
    raise exception 'Invalid normalized Place locality' using errcode = '22023';
  end if;

  insert into public.places (
    trip_id,
    source,
    google_place_id,
    display_name,
    formatted_address,
    latitude,
    longitude,
    locality_name,
    locality_kind,
    country_code,
    administrative_area_name,
    locality_source
  ) values (
    target_trip_id,
    'google',
    btrim(provider_place_id),
    btrim(place_display_name),
    nullif(btrim(place_formatted_address), ''),
    place_latitude,
    place_longitude,
    normalized_locality_name,
    normalized_locality_kind,
    normalized_country_code,
    normalized_administrative_area,
    case when normalized_locality_name is null then null else 'google_address_component' end
  )
  on conflict (trip_id, google_place_id) where google_place_id is not null
  do update set
    display_name = excluded.display_name,
    formatted_address = excluded.formatted_address,
    latitude = excluded.latitude,
    longitude = excluded.longitude,
    locality_name = case
      when excluded.locality_name is not null then excluded.locality_name
      else places.locality_name
    end,
    locality_kind = case
      when excluded.locality_name is not null then excluded.locality_kind
      else places.locality_kind
    end,
    country_code = case
      when excluded.locality_name is not null then excluded.country_code
      else places.country_code
    end,
    administrative_area_name = case
      when excluded.locality_name is not null then excluded.administrative_area_name
      else places.administrative_area_name
    end,
    locality_source = case
      when excluded.locality_name is not null then excluded.locality_source
      else places.locality_source
    end
  returning id into persisted_place_id;

  return persisted_place_id;
end;
$$;

-- Canonical Day order is one short, owner-authorized transaction.  Stable Day
-- IDs retain their Activities; complete date sequences remain position-derived,
-- while incomplete/user-authored date sets stay attached to their Day IDs.
create function public.reorder_variant_days(
  target_trip_id uuid,
  target_variant_id uuid,
  ordered_day_ids uuid[]
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  existing_count integer;
  locked_trip_id uuid;
  current_start date;
  dates_complete boolean;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  select trip.id into locked_trip_id
  from public.trips trip
  where trip.id = target_trip_id
    and trip.owner_id = current_user_id
  for update;

  if locked_trip_id is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.route_variants variant
    where variant.id = target_variant_id
      and variant.trip_id = target_trip_id
  ) then
    raise exception 'VARIANT_NOT_FOUND' using errcode = '22023';
  end if;

  select count(*), min(date), count(date) = count(*)
  into existing_count, current_start, dates_complete
  from public.trip_days
  where variant_id = target_variant_id;

  if ordered_day_ids is null
    or cardinality(ordered_day_ids) <> existing_count
    or (
      select count(distinct submitted.day_id)
      from unnest(ordered_day_ids) submitted(day_id)
    ) <> existing_count
    or exists (
      select 1
      from unnest(ordered_day_ids) submitted(day_id)
      left join public.trip_days day
        on day.id = submitted.day_id
       and day.variant_id = target_variant_id
      where day.id is null
    )
  then
    raise exception 'Submitted Days must exactly match the active route variant'
      using errcode = '22023';
  end if;

  perform day.id
  from public.trip_days day
  where day.variant_id = target_variant_id
  order by day.id
  for update;

  if dates_complete then
    update public.trip_days
    set date = null
    where variant_id = target_variant_id;
  end if;

  update public.trip_days
  set day_number = day_number + 1000
  where variant_id = target_variant_id;

  update public.trip_days day
  set day_number = submitted.position::integer
  from unnest(ordered_day_ids) with ordinality submitted(day_id, position)
  where day.id = submitted.day_id
    and day.variant_id = target_variant_id;

  if dates_complete then
    update public.trip_days
    set date = current_start + (day_number - 1)
    where variant_id = target_variant_id;
  end if;
end;
$$;

-- Fail the migration rather than switching reads with an incomplete deterministic
-- backfill.  These checks do not alter legacy or canonical rows.
do $$
begin
  if exists (
    select 1
    from public.itinerary_items city_item
    join public.places place on place.id = city_item.place_id
    where city_item.type = 'location'
      and place.locality_name is null
  ) then
    raise exception 'ACTIVITY_SSOT_LEGACY_LOCALITY_BACKFILL_INCOMPLETE';
  end if;

  if exists (
    select 1
    from public.itinerary_items item
    left join public.trip_days day on day.id = item.day_id
    left join public.route_variants variant on variant.id = item.variant_id
    where day.id is null
      or day.variant_id is distinct from item.variant_id
      or variant.trip_id is distinct from item.trip_id
  ) then
    raise exception 'ACTIVITY_SSOT_RELATIONSHIP_VERIFICATION_FAILED';
  end if;
end;
$$;

-- Source: supabase/migrations/20260807193302_activity_ssot_public_projection_v2.sql
-- Keep the deployed v1 payload byte-for-byte compatible while the new client
-- adopts Activity-derived locality.  The additive v2 RPC excludes legacy City
-- rows from content, exposes only normalized locality labels/country codes, and
-- retains the v1 City sequence solely as a compatibility fallback for old Trips
-- with no equivalent Activity evidence yet.

create function public.get_public_itinerary_v2(shared_token uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  base_projection jsonb;
  shared record;
  days_projection jsonb;
  cover_cities jsonb;
  locality_summary text;
begin
  base_projection := public.get_public_itinerary(shared_token);
  if coalesce((base_projection ->> 'available')::boolean, false) is false then
    return base_projection;
  end if;

  select
    link.id as link_id,
    link.show_times,
    link.show_map_routes,
    link.show_addresses,
    link.show_notes,
    link.show_quick_action_links,
    link.share_description,
    link.trip_id,
    link.variant_id,
    trip.day_count
  into shared
  from public.public_itinerary_links link
  join public.trips trip on trip.id = link.trip_id
  where link.public_token = shared_token
    and link.revoked_at is null;

  if shared.link_id is null then
    return jsonb_build_object('available', false);
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'ref', encode(extensions.digest(shared.link_id::text || ':day:' || day.id::text, 'sha256'), 'hex'),
          'dayNumber', day.day_number,
          'date', day.date,
          'title', day.title,
          'city', locality.primary_name,
          'primaryLocality', locality.primary_name,
          'localities', coalesce(localities.names, '[]'::jsonb),
          'items', (
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'ref', encode(extensions.digest(shared.link_id::text || ':item:' || item.id::text, 'sha256'), 'hex'),
                  'type', item.type,
                  'title', item.title,
                  'sortOrder', item.sort_order
                )
                || case
                  when shared.show_times then jsonb_strip_nulls(
                    jsonb_build_object(
                      'startTime', item.start_time,
                      'endTime', item.end_time,
                      'scheduleLabel', case
                        when item.schedule_kind = 'all_day' then 'All day'
                        when item.schedule_kind in ('period', 'approximate') then item.schedule_text
                        else null
                      end
                    )
                  )
                  else '{}'::jsonb
                end
                || case
                  when item.type = 'car_rental' then jsonb_build_object(
                    'carRental', jsonb_strip_nulls(
                      jsonb_build_object(
                        'action', case
                          when item.details ->> 'action' in ('pickup', 'return')
                            then item.details ->> 'action'
                          else null
                        end,
                        'company', nullif(btrim(item.details ->> 'provider'), '')
                      )
                      || case
                        when shared.show_addresses then jsonb_strip_nulls(
                          jsonb_build_object(
                            'address', nullif(btrim(item.details ->> 'address'), '')
                          )
                        )
                        else '{}'::jsonb
                      end
                    )
                  )
                  else '{}'::jsonb
                end
                || case
                  when place.id is not null then jsonb_build_object(
                    'place', jsonb_strip_nulls(
                      jsonb_build_object(
                        'displayName', coalesce(place.display_name, item.title),
                        'localityName', place.locality_name,
                        'countryCode', place.country_code,
                        'latitude', case when shared.show_map_routes then place.latitude else null end,
                        'longitude', case when shared.show_map_routes then place.longitude else null end
                      )
                      || case
                        when shared.show_addresses and place.formatted_address is not null
                          then jsonb_build_object('address', place.formatted_address)
                        else '{}'::jsonb
                      end
                    )
                  )
                  else '{}'::jsonb
                end
                || case
                  when shared.show_notes and item.notes is not null
                    then jsonb_build_object('notes', item.notes)
                  else '{}'::jsonb
                end
                || case
                  when shared.show_quick_action_links then (
                    select case
                      when count(*) = 0 then '{}'::jsonb
                      else jsonb_build_object(
                        'links', jsonb_agg(
                          jsonb_build_object('label', btrim(link.label), 'url', link.url)
                          order by link.sort_order, link.id
                        )
                      )
                    end
                    from public.itinerary_item_links link
                    where link.item_id = item.id
                      and link.url ~* '^https?://[^[:space:]]+$'
                  )
                  else '{}'::jsonb
                end
                order by item.sort_order, item.id
              ),
              '[]'::jsonb
            )
            from public.itinerary_items item
            left join public.places place
              on place.id = item.place_id
             and place.trip_id = shared.trip_id
            where item.day_id = day.id
              and item.variant_id = shared.variant_id
              and item.trip_id = shared.trip_id
              and item.type <> 'location'
              and (item.type <> 'note' or shared.show_notes)
          )
        )
        || case
          when shared.show_notes and day.notes is not null
            then jsonb_build_object('notes', day.notes)
          else '{}'::jsonb
        end
      ) order by day.day_number, day.id
    ),
    '[]'::jsonb
  ) into days_projection
  from public.trip_days day
  left join lateral (
    select coalesce(
      (
        select place.locality_name
        from public.itinerary_items item
        join public.places place
          on place.id = item.place_id
         and place.trip_id = shared.trip_id
        where item.day_id = day.id
          and item.variant_id = shared.variant_id
          and item.trip_id = shared.trip_id
          and item.type = 'hotel'
          and place.locality_name is not null
        order by item.sort_order desc, item.id desc
        limit 1
      ),
      (
        select dominant.name
        from (
          select
            (array_agg(place.locality_name order by item.sort_order, item.id))[1] as name,
            count(*) as frequency,
            min(item.sort_order) as first_sort
          from public.itinerary_items item
          join public.places place
            on place.id = item.place_id
           and place.trip_id = shared.trip_id
          where item.day_id = day.id
            and item.variant_id = shared.variant_id
            and item.trip_id = shared.trip_id
            and item.type not in ('location', 'note')
            and place.locality_name is not null
          group by coalesce(place.country_code, ''), lower(btrim(place.locality_name))
          order by frequency desc, first_sort, name
          limit 1
        ) dominant
      ),
      (
        select coalesce(place.locality_name, place.display_name, item.title)
        from public.itinerary_items item
        left join public.places place
          on place.id = item.place_id
         and place.trip_id = shared.trip_id
        where item.day_id = day.id
          and item.variant_id = shared.variant_id
          and item.trip_id = shared.trip_id
          and item.type = 'location'
        order by item.sort_order, item.id
        limit 1
      )
    ) as primary_name
  ) locality on true
  left join lateral (
    select coalesce(
      (
        select jsonb_agg(canonical.name order by canonical.first_sort, canonical.first_id)
        from (
          select distinct on (
            coalesce(place.country_code, ''),
            lower(btrim(place.locality_name))
          )
            place.locality_name as name,
            item.sort_order as first_sort,
            item.id as first_id
          from public.itinerary_items item
          join public.places place
            on place.id = item.place_id
           and place.trip_id = shared.trip_id
          where item.day_id = day.id
            and item.variant_id = shared.variant_id
            and item.trip_id = shared.trip_id
            and item.type not in ('location', 'note')
            and place.locality_name is not null
          order by
            coalesce(place.country_code, ''),
            lower(btrim(place.locality_name)),
            item.sort_order,
            item.id
        ) canonical
      ),
      (
        select jsonb_agg(legacy.name order by legacy.first_sort, legacy.first_id)
        from (
          select distinct on (lower(btrim(coalesce(place.locality_name, place.display_name, item.title))))
            coalesce(place.locality_name, place.display_name, item.title) as name,
            item.sort_order as first_sort,
            item.id as first_id
          from public.itinerary_items item
          left join public.places place
            on place.id = item.place_id
           and place.trip_id = shared.trip_id
          where item.day_id = day.id
            and item.variant_id = shared.variant_id
            and item.trip_id = shared.trip_id
            and item.type = 'location'
          order by
            lower(btrim(coalesce(place.locality_name, place.display_name, item.title))),
            item.sort_order,
            item.id
        ) legacy
      ),
      '[]'::jsonb
    ) as names
  ) localities on true
  where day.variant_id = shared.variant_id;

  select
    coalesce(jsonb_agg(locality.name order by locality.first_day), '[]'::jsonb),
    string_agg(locality.name, ' · ' order by locality.first_day)
  into cover_cities, locality_summary
  from (
    select
      min((entry.value ->> 'dayNumber')::integer) as first_day,
      entry.value ->> 'primaryLocality' as name
    from jsonb_array_elements(days_projection) entry(value)
    where entry.value ->> 'primaryLocality' is not null
    group by entry.value ->> 'primaryLocality'
    order by first_day
    limit 3
  ) locality;

  return base_projection
    || jsonb_build_object('days', days_projection)
    || jsonb_build_object(
      'metadata', jsonb_build_object(
        'title', base_projection -> 'metadata' ->> 'title',
        'description', coalesce(
          shared.share_description,
          shared.day_count || '-day itinerary'
            || case when locality_summary is null then '' else ' · ' || locality_summary end
            || ' · View plans, tickets and routes'
        ),
        'coverCities', cover_cities
      )
    );
end;
$$;

-- Source: supabase/migrations/20260808022426_enforce_hotel_last_activity_order.sql
-- Existing Days keep every Item and relationship. Only their dense manual positions change:
-- relative non-Hotel order is preserved and the single permitted Hotel becomes the final Item.
with ranked as (
  select
    item.id,
    row_number() over (
      partition by item.day_id
      order by
        case when item.type = 'hotel' then 1 else 0 end,
        item.sort_order,
        item.id
    ) - 1 as next_sort_order
  from public.itinerary_items item
), changed as (
  select ranked.id, ranked.next_sort_order
  from ranked
  join public.itinerary_items item on item.id = ranked.id
  where item.sort_order is distinct from ranked.next_sort_order
)
update public.itinerary_items item
set sort_order = changed.next_sort_order
from changed
where item.id = changed.id;

create or replace function public.reorder_itinerary_items(
  target_day_id uuid,
  ordered_item_ids uuid[]
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_trip_id uuid;
  existing_count integer;
begin
  select route_variants.trip_id
  into target_trip_id
  from public.trip_days
  join public.route_variants on route_variants.id = trip_days.variant_id
  where trip_days.id = target_day_id;

  if target_trip_id is null or not public.is_trip_owner(target_trip_id) then
    raise exception 'Trip owner access required' using errcode = '42501';
  end if;

  if ordered_item_ids is null then
    raise exception 'Item order is required' using errcode = '22023';
  end if;

  select count(*) into existing_count
  from public.itinerary_items
  where day_id = target_day_id;

  if cardinality(ordered_item_ids) <> existing_count
    or (select count(distinct item_id) from unnest(ordered_item_ids) as item_id) <> existing_count
    or exists (
      select 1
      from unnest(ordered_item_ids) as submitted(item_id)
      left join public.itinerary_items
        on itinerary_items.id = submitted.item_id
        and itinerary_items.day_id = target_day_id
      where itinerary_items.id is null
    )
  then
    raise exception 'Submitted items must exactly match the day itinerary' using errcode = '22023';
  end if;

  if exists (
    select 1
    from unnest(ordered_item_ids) with ordinality as submitted(item_id, position)
    join public.itinerary_items item on item.id = submitted.item_id
    where item.type = 'hotel' and submitted.position <> existing_count
  ) then
    raise exception 'Hotel must be the final itinerary item' using errcode = '22023';
  end if;

  update public.itinerary_items
  set sort_order = submitted.position - 1
  from unnest(ordered_item_ids) with ordinality as submitted(item_id, position)
  where itinerary_items.id = submitted.item_id;
end;
$$;

-- Source: supabase/migrations/20260809161845_phase_6b_research_foundations.sql
-- Phase 6B-A/6B-B keeps private travel research outside canonical itinerary
-- truth. Ideas may remain unclassified; Options always belong to a comparison
-- context, and provenance is normalized through a join table.

create table public.research_topics (
  id uuid primary key default gen_random_uuid(),
  trip_id uuid not null references public.trips (id) on delete cascade,
  label text not null,
  label_key text generated always as (lower(btrim(label))) stored,
  category text not null default 'general',
  scope_kind text not null default 'trip',
  variant_id uuid references public.route_variants (id) on delete set null,
  day_id uuid references public.trip_days (id) on delete set null,
  end_day_id uuid references public.trip_days (id) on delete set null,
  itinerary_item_id uuid references public.itinerary_items (id) on delete set null,
  scope_label text,
  scope_label_key text generated always as (
    case when scope_label is null then null else lower(btrim(scope_label)) end
  ) stored,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint research_topics_id_trip_unique unique (id, trip_id),
  constraint research_topics_context_unique unique nulls not distinct (
    trip_id,
    label_key,
    category,
    scope_kind,
    variant_id,
    day_id,
    end_day_id,
    itinerary_item_id,
    scope_label_key
  ),
  constraint research_topics_label_length
    check (char_length(btrim(label)) between 1 and 160),
  constraint research_topics_category_check
    check (category in ('flight', 'stay', 'train', 'rental', 'activity', 'general')),
  constraint research_topics_scope_kind_check
    check (scope_kind in ('trip', 'day', 'day_range', 'itinerary_item', 'segment', 'place', 'freeform')),
  constraint research_topics_scope_label_length
    check (scope_label is null or char_length(btrim(scope_label)) between 1 and 300),
  constraint research_topics_details_object check (jsonb_typeof(details) = 'object'),
  constraint research_topics_scope_references check (
    (scope_kind <> 'day' or day_id is not null)
    and (scope_kind <> 'day_range' or (day_id is not null and end_day_id is not null))
    and (scope_kind <> 'itinerary_item' or itinerary_item_id is not null)
    and (scope_kind not in ('segment', 'place', 'freeform') or scope_label is not null)
  )
);

create table public.research_entries (
  id uuid primary key default gen_random_uuid(),
  trip_id uuid not null references public.trips (id) on delete cascade,
  topic_id uuid,
  raw_text text not null,
  source_url text,
  capture_type text not null default 'text',
  category text,
  scope_kind text not null default 'inbox',
  variant_id uuid references public.route_variants (id) on delete set null,
  day_id uuid references public.trip_days (id) on delete set null,
  end_day_id uuid references public.trip_days (id) on delete set null,
  itinerary_item_id uuid references public.itinerary_items (id) on delete set null,
  scope_label text,
  attachment_refs jsonb not null default '[]'::jsonb,
  extraction_status text not null default 'not_requested',
  source_metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint research_entries_id_trip_unique unique (id, trip_id),
  constraint research_entries_topic_trip_fkey foreign key (topic_id, trip_id)
    references public.research_topics (id, trip_id) on delete set null (topic_id),
  constraint research_entries_raw_text_length
    check (char_length(btrim(raw_text)) between 1 and 5000),
  constraint research_entries_source_url_format
    check (source_url is null or (char_length(source_url) <= 2048 and source_url ~ '^https?://')),
  constraint research_entries_capture_type_check
    check (capture_type in ('text', 'url', 'price', 'reminder', 'screenshot', 'other')),
  constraint research_entries_category_check
    check (category is null or category in ('flight', 'stay', 'train', 'rental', 'activity', 'general')),
  constraint research_entries_scope_kind_check
    check (scope_kind in ('inbox', 'trip', 'day', 'day_range', 'itinerary_item', 'segment', 'place', 'freeform')),
  constraint research_entries_scope_label_length
    check (scope_label is null or char_length(btrim(scope_label)) between 1 and 300),
  constraint research_entries_attachment_refs_array
    check (jsonb_typeof(attachment_refs) = 'array'),
  constraint research_entries_extraction_status_check
    check (extraction_status in ('not_requested', 'pending', 'processing', 'complete', 'failed')),
  constraint research_entries_source_metadata_object
    check (jsonb_typeof(source_metadata) = 'object'),
  constraint research_entries_scope_references check (
    (scope_kind <> 'day' or day_id is not null)
    and (scope_kind <> 'day_range' or (day_id is not null and end_day_id is not null))
    and (scope_kind <> 'itinerary_item' or itinerary_item_id is not null)
    and (scope_kind not in ('segment', 'place', 'freeform') or scope_label is not null)
  )
);

create table public.research_options (
  id uuid primary key default gen_random_uuid(),
  trip_id uuid not null references public.trips (id) on delete cascade,
  topic_id uuid not null,
  category text not null,
  title text not null,
  provider_label text,
  source_url text,
  relevant_start_date date,
  relevant_end_date date,
  search_context text,
  total_price numeric(12, 2),
  currency text,
  price_basis text not null default 'total',
  taxes_included boolean,
  observed_at timestamptz not null default now(),
  structured_details jsonb not null default '{}'::jsonb,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint research_options_id_trip_unique unique (id, trip_id),
  constraint research_options_topic_trip_fkey foreign key (topic_id, trip_id)
    references public.research_topics (id, trip_id) on delete cascade,
  constraint research_options_category_check
    check (category in ('flight', 'stay', 'train', 'rental', 'activity', 'general')),
  constraint research_options_title_length
    check (char_length(btrim(title)) between 1 and 300),
  constraint research_options_provider_length
    check (provider_label is null or char_length(btrim(provider_label)) between 1 and 160),
  constraint research_options_source_url_format
    check (source_url is null or (char_length(source_url) <= 2048 and source_url ~ '^https?://')),
  constraint research_options_date_order
    check (relevant_end_date is null or relevant_start_date is null or relevant_end_date >= relevant_start_date),
  constraint research_options_search_context_length
    check (search_context is null or char_length(btrim(search_context)) between 1 and 1000),
  constraint research_options_total_price_nonnegative
    check (total_price is null or total_price >= 0),
  constraint research_options_currency_format
    check ((total_price is null and currency is null) or currency ~ '^[A-Z]{3}$'),
  constraint research_options_price_basis_check
    check (price_basis in ('total', 'per_night', 'per_person', 'per_segment', 'other', 'unknown')),
  constraint research_options_structured_details_object
    check (jsonb_typeof(structured_details) = 'object'),
  constraint research_options_notes_length
    check (notes is null or char_length(notes) <= 5000)
);

create table public.research_option_entries (
  trip_id uuid not null references public.trips (id) on delete cascade,
  option_id uuid not null,
  entry_id uuid not null,
  created_at timestamptz not null default now(),
  primary key (option_id, entry_id),
  constraint research_option_entries_option_trip_fkey foreign key (option_id, trip_id)
    references public.research_options (id, trip_id) on delete cascade,
  constraint research_option_entries_entry_trip_fkey foreign key (entry_id, trip_id)
    references public.research_entries (id, trip_id) on delete cascade
);

create index research_topics_trip_updated_idx
  on public.research_topics (trip_id, updated_at desc);

create index research_topics_scope_idx
  on public.research_topics (trip_id, variant_id, day_id, itinerary_item_id);

create index research_entries_trip_created_idx
  on public.research_entries (trip_id, created_at desc);

create index research_entries_topic_idx
  on public.research_entries (topic_id) where topic_id is not null;

create index research_entries_scope_idx
  on public.research_entries (trip_id, variant_id, day_id, itinerary_item_id);

create index research_options_trip_category_idx
  on public.research_options (trip_id, category, observed_at desc);

create index research_options_topic_idx
  on public.research_options (topic_id, observed_at desc);

create index research_option_entries_entry_idx
  on public.research_option_entries (entry_id, option_id);

create trigger research_topics_set_updated_at
before update on public.research_topics
for each row execute function public.set_updated_at();

create trigger research_entries_set_updated_at
before update on public.research_entries
for each row execute function public.set_updated_at();

create trigger research_options_set_updated_at
before update on public.research_options
for each row execute function public.set_updated_at();

create or replace function public.research_context_matches_trip(
  target_trip_id uuid,
  target_variant_id uuid,
  target_day_id uuid,
  target_end_day_id uuid,
  target_itinerary_item_id uuid
)
returns boolean
language sql
stable
security invoker
set search_path = ''
as $$
  select
    (
      target_variant_id is null
      or exists (
        select 1 from public.route_variants variant
        where variant.id = target_variant_id and variant.trip_id = target_trip_id
      )
    )
    and (
      target_day_id is null
      or exists (
        select 1
        from public.trip_days day
        join public.route_variants variant on variant.id = day.variant_id
        where day.id = target_day_id and variant.trip_id = target_trip_id
      )
    )
    and (
      target_end_day_id is null
      or exists (
        select 1
        from public.trip_days day
        join public.route_variants variant on variant.id = day.variant_id
        where day.id = target_end_day_id and variant.trip_id = target_trip_id
      )
    )
    and (
      target_itinerary_item_id is null
      or exists (
        select 1 from public.itinerary_items item
        where item.id = target_itinerary_item_id and item.trip_id = target_trip_id
      )
    );
$$;

