-- Source: supabase/migrations/20260811121345_detach_deleted_research_history.sql
-- Deleting a saved Research candidate must not be blocked by durable Apply
-- history. Keep the narrow before/after snapshots for audit and safe Revert,
-- while removing the live foreign-key relationship to the deleted candidate.

set lock_timeout = '5s';

set statement_timeout = '30s';

alter table public.research_plan_applications
  drop constraint research_plan_applications_research_trip_fkey;

alter table public.research_plan_applications
  alter column source_research_item_id drop not null;

alter table public.research_plan_applications
  add constraint research_plan_applications_research_trip_fkey
  foreign key (source_research_item_id, trip_id)
  references public.research_items (id, trip_id)
  on delete set null (source_research_item_id);

comment on column public.research_plan_applications.source_research_item_id is
  'Source ResearchItem when it still exists. NULL after the saved candidate is deleted; durable Apply snapshots remain available.';

-- Source: supabase/migrations/20260811151042_canonical_plan_prices_and_current_applications.sql
-- Canonical Plan pricing and current-aware Research application state.
-- A price belongs to the canonical itinerary item that contributes to Known
-- Cost. Multi-row bookings store their total on one intentional anchor item.

set lock_timeout = '5s';

set statement_timeout = '30s';

alter table public.itinerary_items
  add column price_amount numeric(12, 2),
  add column price_currency text;

alter table public.itinerary_items
  add constraint itinerary_items_price_nonnegative
    check (price_amount is null or price_amount >= 0),
  add constraint itinerary_items_price_currency_pair check (
    (price_amount is null and price_currency is null)
    or (price_amount is not null and price_currency ~ '^[A-Z]{3}$')
  );

comment on column public.itinerary_items.price_amount is
  'Canonical Plan cost contribution. A multi-item booking records its total on exactly one anchor item.';

comment on column public.itinerary_items.price_currency is
  'ISO 4217 currency for price_amount. Known Cost groups currencies without conversion.';

