  rename to apply_research_item_to_variant_v2_phase_6b_schedule;

create function public.apply_research_item_to_variant_v2(
  target_trip_id uuid,
  target_variant_id uuid,
  target_research_item_id uuid,
  target_item_id uuid default null,
  schedule_choice text default 'automatic'
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  source_item public.research_items%rowtype;
  previous_application public.research_plan_applications%rowtype;
  saved_application public.research_plan_applications%rowtype;
  canonical_item public.itinerary_items%rowtype;
  apply_result jsonb;
  application_id uuid;
  operation jsonb;
  patched_operations jsonb;
  operation_index integer;
  next_amount numeric(12, 2);
  next_currency text;
  is_price_anchor boolean;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  perform 1 from public.trips trip
  where trip.id = target_trip_id and trip.owner_id = current_user_id for update;
  if not found then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;
  select * into source_item from public.research_items item
  where item.id = target_research_item_id and item.trip_id = target_trip_id for update;
  if source_item.id is null then
    raise exception 'RESEARCH_ITEM_NOT_FOUND' using errcode = '22023';
  end if;

  -- An active history row is only idempotent while both its source candidate
  -- and its affected canonical entities still represent that exact Apply.
  for previous_application in
    select * from public.research_plan_applications application
    where application.route_variant_id = target_variant_id
      and application.source_research_item_id = target_research_item_id
      and application.status = 'applied'
    for update
  loop
    if source_item.updated_at > previous_application.applied_at
      or not public.research_application_matches_current(previous_application.id)
      or not exists (
        select 1
        from jsonb_array_elements(previous_application.operations) entry(value)
        where entry.value ->> 'kind' in ('create_item', 'update_item')
          and entry.value -> 'after' ? 'price_amount'
      )
      or exists (
        select 1
        from jsonb_array_elements(previous_application.operations) entry(value)
        join public.itinerary_items item
          on item.id = (entry.value ->> 'entityId')::uuid
        where entry.value ->> 'kind' in ('create_item', 'update_item')
          and item.updated_at > previous_application.applied_at
      ) then
      update public.research_plan_applications
      set status = 'superseded', superseded_at = clock_timestamp()
      where id = previous_application.id;
    end if;
  end loop;

  apply_result := public.apply_research_item_to_variant_v2_phase_6b_schedule(
    target_trip_id,
    target_variant_id,
    target_research_item_id,
    target_item_id,
    schedule_choice
  );
  if coalesce((apply_result ->> 'idempotent')::boolean, false) then
    return apply_result;
  end if;

  application_id := (apply_result ->> 'applicationId')::uuid;
  select * into saved_application
  from public.research_plan_applications application
  where application.id = application_id for update;
  patched_operations := saved_application.operations;

  for operation_index in 0..jsonb_array_length(patched_operations) - 1 loop
    operation := patched_operations -> operation_index;
    if operation ->> 'kind' not in ('create_item', 'update_item') then
      continue;
    end if;
    select * into canonical_item from public.itinerary_items item
    where item.id = (operation ->> 'entityId')::uuid
      and item.trip_id = target_trip_id
      and item.variant_id = target_variant_id
    for update;
    if canonical_item.id is null
      or canonical_item.details ->> 'researchSourceId' is distinct from target_research_item_id::text then
      continue;
    end if;

    is_price_anchor := case source_item.category
      when 'flight' then canonical_item.details ->> 'segmentIndex' = '0'
      when 'train' then canonical_item.details ->> 'segmentIndex' = '0'
      when 'rental' then canonical_item.details ->> 'action' = 'pickup'
      when 'stay' then canonical_item.id = (
        select item.id
        from jsonb_array_elements(patched_operations) entry(value)
        join public.itinerary_items item
          on item.id = (entry.value ->> 'entityId')::uuid
        join public.trip_days day on day.id = item.day_id
        where entry.value ->> 'kind' in ('create_item', 'update_item')
          and item.trip_id = target_trip_id
          and item.variant_id = target_variant_id
          and item.type = 'hotel'
          and item.details ->> 'researchSourceId' = target_research_item_id::text
        order by day.date nulls last, day.day_number, item.id
        limit 1
      )
      else false
    end;
    next_amount := case when is_price_anchor then source_item.total_price_amount else null end;
    next_currency := case when is_price_anchor then source_item.currency else null end;

    if operation ->> 'kind' = 'update_item' then
      operation := jsonb_set(
        operation,
        '{before,price_amount}',
        coalesce(to_jsonb(canonical_item.price_amount), 'null'::jsonb),
        true
      );
      operation := jsonb_set(
        operation,
        '{before,price_currency}',
        coalesce(to_jsonb(canonical_item.price_currency), 'null'::jsonb),
        true
      );
    end if;

    update public.itinerary_items item
    set price_amount = next_amount, price_currency = next_currency
    where item.id = canonical_item.id
    returning * into canonical_item;

    operation := jsonb_set(
      operation,
      '{after,price_amount}',
      coalesce(to_jsonb(canonical_item.price_amount), 'null'::jsonb),
      true
    );
    operation := jsonb_set(
      operation,
      '{after,price_currency}',
      coalesce(to_jsonb(canonical_item.price_currency), 'null'::jsonb),
      true
    );
    if operation ->> 'kind' = 'create_item' then
      operation := jsonb_set(
        operation,
        '{after,updated_at}',
        to_jsonb(canonical_item.updated_at),
        true
      );
    end if;
    patched_operations := jsonb_set(
      patched_operations,
      array[operation_index::text],
      operation,
      false
    );
  end loop;

  update public.research_plan_applications application
  set operations = patched_operations,
      before_snapshot = (
        select coalesce(jsonb_agg(
          coalesce(entry.value -> 'before', 'null'::jsonb) order by entry.ordinality
        ), '[]'::jsonb)
        from jsonb_array_elements(patched_operations) with ordinality entry(value, ordinality)
      ),
      after_snapshot = (
        select coalesce(jsonb_agg(
          coalesce(entry.value -> 'after', 'null'::jsonb) order by entry.ordinality
        ), '[]'::jsonb)
        from jsonb_array_elements(patched_operations) with ordinality entry(value, ordinality)
      ),
      applied_at = clock_timestamp()
  where application.id = application_id
  returning * into saved_application;

  return apply_result || jsonb_build_object('appliedAt', saved_application.applied_at);
end;
$$;

comment on function public.apply_research_item_to_variant_v2(uuid, uuid, uuid, uuid, text) is
  'Atomically selects and applies a Research booking, synchronizes the Plan schedule, stores one canonical price contribution, and records conflict-safe history.';

alter function public.revert_research_plan_application(uuid, uuid)
  rename to revert_research_plan_application_phase_6b_schedule;

create function public.revert_research_plan_application(
  target_trip_id uuid,
  target_application_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  application_row public.research_plan_applications%rowtype;
  revert_result jsonb;
  operation jsonb;
  before_values jsonb;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  perform 1 from public.trips trip
  where trip.id = target_trip_id and trip.owner_id = current_user_id for update;
  if not found then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;
  select * into application_row from public.research_plan_applications application
  where application.id = target_application_id
    and application.trip_id = target_trip_id
  for update;
  if application_row.id is null then
    raise exception 'RESEARCH_APPLICATION_NOT_FOUND' using errcode = '22023';
  end if;
  if application_row.status = 'reverted' then
    return jsonb_build_object(
      'applicationId', application_row.id,
      'status', 'reverted',
      'revertedAt', application_row.reverted_at
    );
  end if;

  revert_result := public.revert_research_plan_application_phase_6b_schedule(
    target_trip_id,
    target_application_id
  );
  if revert_result ->> 'status' <> 'reverted' then
    return revert_result;
  end if;

  for operation in
    select value from jsonb_array_elements(application_row.operations)
    where value ->> 'kind' = 'update_item'
      and (value -> 'before' ? 'price_amount' or value -> 'before' ? 'price_currency')
  loop
    before_values := operation -> 'before';
    update public.itinerary_items item
    set price_amount = case
          when before_values ? 'price_amount'
            then nullif(before_values ->> 'price_amount', '')::numeric
          else item.price_amount
        end,
        price_currency = case
          when before_values ? 'price_currency'
            then nullif(before_values ->> 'price_currency', '')
          else item.price_currency
        end
    where item.id = (operation ->> 'entityId')::uuid
      and item.trip_id = target_trip_id
      and item.variant_id = application_row.route_variant_id;
  end loop;
  return revert_result;
end;
$$;

comment on function public.revert_research_plan_application(uuid, uuid) is
  'Conflict-safe durable Revert for canonical booking fields, prices, and Apply-owned Plan schedule changes.';

create function public.current_research_plan_application_ids(
  target_trip_id uuid,
  target_variant_id uuid
) returns uuid[]
language plpgsql
security definer
stable
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  current_ids uuid[];
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  perform 1 from public.trips trip
  where trip.id = target_trip_id and trip.owner_id = current_user_id;
  if not found then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.route_variants variant
    where variant.id = target_variant_id and variant.trip_id = target_trip_id
  ) then
    raise exception 'VARIANT_NOT_FOUND' using errcode = '22023';
  end if;

  select coalesce(array_agg(application.id order by application.applied_at desc), '{}'::uuid[])
  into current_ids
  from public.research_plan_applications application
  join public.research_items source
    on source.id = application.source_research_item_id
    and source.trip_id = application.trip_id
  where application.trip_id = target_trip_id
    and application.route_variant_id = target_variant_id
    and application.status = 'applied'
    and source.updated_at <= application.applied_at
    and public.research_application_matches_current(application.id)
    and exists (
      select 1 from jsonb_array_elements(application.operations) entry(value)
      where entry.value ->> 'kind' in ('create_item', 'update_item')
        and entry.value -> 'after' ? 'price_amount'
    )
    and not exists (
      select 1
      from jsonb_array_elements(application.operations) entry(value)
      join public.itinerary_items item
        on item.id = (entry.value ->> 'entityId')::uuid
      where entry.value ->> 'kind' in ('create_item', 'update_item')
        and item.updated_at > application.applied_at
    );
  return current_ids;
end;
$$;

comment on function public.current_research_plan_application_ids(uuid, uuid) is
  'Returns owner-only Apply history IDs that still match both the current Research source and current canonical Plan entities.';

-- Source: supabase/migrations/20260811153435_harden_canonical_plan_price_eligibility.sql
-- Make the canonical price pair fully two-valued. PostgreSQL CHECK accepts an
-- unknown expression, so price_currency must be explicitly non-null when an
-- amount is present. Also enforce the one-anchor rental rule at the database.

set lock_timeout = '5s';

set statement_timeout = '30s';

alter table public.itinerary_items
  drop constraint itinerary_items_price_currency_pair;

alter table public.itinerary_items
  add constraint itinerary_items_price_currency_pair check (
    (price_amount is null and price_currency is null)
    or (
      price_amount is not null
      and price_currency is not null
      and price_currency ~ '^[A-Z]{3}$'
    )
  ),
  add constraint itinerary_items_price_eligible_type check (
    price_amount is null
    or (
      type not in ('location', 'note')
      and not (
        type = 'car_rental'
        and details ->> 'action' = 'return'
      )
    )
  );

comment on constraint itinerary_items_price_eligible_type on public.itinerary_items is
  'Known Cost excludes non-bookable rows and stores a Rental total only on its pickup anchor.';

-- Source: supabase/migrations/20260811154500_normalize_legacy_flight_journeys_before_apply.sql
-- Compatibility for Flights saved before journey_type/segments existed.
-- Their top-level From/To and outbound/return dates already contain the full
-- intent, so normalize that same record before entering the current Apply RPC.

set lock_timeout = '5s';

set statement_timeout = '30s';

alter function public.apply_research_item_to_variant_v2(uuid, uuid, uuid, uuid, text)
  rename to apply_research_item_to_variant_v2_phase_6b_canonical_price;

create function public.apply_research_item_to_variant_v2(
  target_trip_id uuid,
  target_variant_id uuid,
  target_research_item_id uuid,
  target_item_id uuid default null,
  schedule_choice text default 'automatic'
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  source_item public.research_items%rowtype;
  normalized_segments jsonb;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  perform 1 from public.trips trip
  where trip.id = target_trip_id and trip.owner_id = current_user_id for update;
  if not found then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;
  select * into source_item from public.research_items item
  where item.id = target_research_item_id and item.trip_id = target_trip_id for update;
  if source_item.id is null then
    raise exception 'RESEARCH_ITEM_NOT_FOUND' using errcode = '22023';
  end if;

  if source_item.category = 'flight'
    and source_item.journey_type is null
    and jsonb_array_length(source_item.segments) = 0
    and source_item.origin_text is not null
    and source_item.destination_text is not null
    and source_item.start_date is not null then
    normalized_segments := jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'origin', source_item.origin_text,
      'destination', source_item.destination_text,
      'departureDate', source_item.start_date,
      'departureTime', source_item.start_time,
      'arrivalDate', source_item.start_date,
      'arrivalTime', source_item.end_time
    )));
    if source_item.end_date is not null then
      normalized_segments := normalized_segments || jsonb_build_array(jsonb_build_object(
        'origin', source_item.destination_text,
        'destination', source_item.origin_text,
        'departureDate', source_item.end_date,
        'arrivalDate', source_item.end_date
      ));
    end if;
    update public.research_items item
    set journey_type = case when source_item.end_date is null then 'one_way' else 'round_trip' end,
        segments = normalized_segments
    where item.id = source_item.id;
  end if;

  return public.apply_research_item_to_variant_v2_phase_6b_canonical_price(
    target_trip_id,
    target_variant_id,
    target_research_item_id,
    target_item_id,
    schedule_choice
  );
end;
$$;

comment on function public.apply_research_item_to_variant_v2(uuid, uuid, uuid, uuid, text) is
  'Current atomic Apply boundary. Normalizes legacy top-level Flight routes, then applies schedule, canonical details and one canonical price contribution with durable history.';

-- Source: supabase/migrations/20260811170608_apply_complete_booking_fields.sql
-- Make Research Apply replace the complete canonical booking field set.
-- Missing optional Research values intentionally clear stale canonical values.

set lock_timeout = '5s';

set statement_timeout = '30s';

create or replace function public.research_owned_item_snapshot(
  target_item public.itinerary_items
) returns jsonb
language sql
immutable
security invoker
set search_path = ''
as $$
  select jsonb_build_object(
    'type', target_item.type,
    'title', target_item.title,
    'day_id', target_item.day_id,
    'start_time', target_item.start_time,
    'end_time', target_item.end_time,
    'schedule_kind', target_item.schedule_kind,
    'schedule_text', target_item.schedule_text,
    'place_id', target_item.place_id,
    'notes', target_item.notes,
    'booking_url', target_item.booking_url,
    'details', target_item.details,
    'price_amount', target_item.price_amount,
    'price_currency', target_item.price_currency
  );
$$;

-- Repair any legacy duplicate anchors before enforcing one canonical price for
-- one Research booking in one Plan.
with duplicate_anchors as (
  select item.id,
         row_number() over (
           partition by item.variant_id, item.details ->> 'researchSourceId'
           order by case
                      when item.details ->> 'segmentIndex' ~ '^\d+$'
                        then (item.details ->> 'segmentIndex')::integer
                      else 0
                    end,
                    item.created_at, item.id
         ) as anchor_number
  from public.itinerary_items item
  where item.price_amount is not null
    and nullif(item.details ->> 'researchSourceId', '') is not null
)
update public.itinerary_items item
set price_amount = null, price_currency = null
from duplicate_anchors anchor
where anchor.id = item.id and anchor.anchor_number > 1;

create unique index itinerary_items_one_price_per_research_booking
  on public.itinerary_items (variant_id, ((details ->> 'researchSourceId')))
  where price_amount is not null
    and nullif(details ->> 'researchSourceId', '') is not null;

alter function public.apply_research_item_to_variant_v2(uuid, uuid, uuid, uuid, text)
  rename to apply_research_item_to_variant_v2_phase_6b_legacy_journey;

create function public.apply_research_item_to_variant_v2(
  target_trip_id uuid,
  target_variant_id uuid,
  target_research_item_id uuid,
  target_item_id uuid default null,
  schedule_choice text default 'automatic'
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  source_item public.research_items%rowtype;
  canonical_item public.itinerary_items%rowtype;
  saved_application public.research_plan_applications%rowtype;
  apply_result jsonb;
  application_id uuid;
  prior_items jsonb := '{}'::jsonb;
  patched_operations jsonb;
  operation jsonb;
  before_values jsonb;
  after_values jsonb;
  next_details jsonb;
  source_segment jsonb;
  operation_index integer;
  segment_index integer;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  perform 1 from public.trips trip
  where trip.id = target_trip_id and trip.owner_id = current_user_id for update;
  if not found then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.route_variants variant
    where variant.id = target_variant_id and variant.trip_id = target_trip_id
  ) then
    raise exception 'VARIANT_NOT_FOUND' using errcode = '22023';
  end if;
  select * into source_item from public.research_items item
  where item.id = target_research_item_id and item.trip_id = target_trip_id for update;
  if source_item.id is null then
    raise exception 'RESEARCH_ITEM_NOT_FOUND' using errcode = '22023';
  end if;

  -- Apply is rare and short. Lock only booking rows of the relevant category,
  -- in deterministic ID order, so their full before state is durable.
  select coalesce(jsonb_object_agg(item.id::text, public.research_owned_item_snapshot(item)), '{}'::jsonb)
  into prior_items
  from (
    select candidate.*
    from public.itinerary_items candidate
    where candidate.trip_id = target_trip_id
      and candidate.variant_id = target_variant_id
      and case source_item.category
        when 'flight' then candidate.type in ('transport', 'flight')
        when 'train' then candidate.type in ('transport', 'train')
        when 'stay' then candidate.type = 'hotel'
        when 'rental' then candidate.type = 'car_rental'
        else false
      end
    order by candidate.id
    for update
  ) item;

  -- Existing pre-migration applications did not own null-clearing fields, so
  -- they must pass through the current Apply boundary once to become complete.
  update public.research_plan_applications application
  set status = 'superseded', superseded_at = clock_timestamp()
  where application.trip_id = target_trip_id
    and application.route_variant_id = target_variant_id
    and application.source_research_item_id = target_research_item_id
    and application.status = 'applied'
    and not exists (
      select 1 from jsonb_array_elements(application.operations) entry(value)
      where entry.value ->> 'kind' in ('create_item', 'update_item')
        and entry.value -> 'after' ? 'notes'
        and entry.value -> 'after' ? 'type'
        and entry.value -> 'after' ? 'schedule_text'
    );

  apply_result := public.apply_research_item_to_variant_v2_phase_6b_legacy_journey(
    target_trip_id,
    target_variant_id,
    target_research_item_id,
    target_item_id,
    schedule_choice
  );
  if coalesce((apply_result ->> 'idempotent')::boolean, false) then
    return apply_result;
  end if;

  -- The compatibility layer may normalize legacy journey segments.
  select * into source_item from public.research_items item
  where item.id = target_research_item_id and item.trip_id = target_trip_id for update;
  application_id := (apply_result ->> 'applicationId')::uuid;
  select * into saved_application from public.research_plan_applications application
  where application.id = application_id for update;
  patched_operations := saved_application.operations;

  for operation_index in 0..jsonb_array_length(patched_operations) - 1 loop
    operation := patched_operations -> operation_index;
    if operation ->> 'kind' not in ('create_item', 'update_item') then
      continue;
    end if;
    select * into canonical_item from public.itinerary_items item
    where item.id = (operation ->> 'entityId')::uuid
      and item.trip_id = target_trip_id
      and item.variant_id = target_variant_id
    for update;
    if canonical_item.id is null
      or canonical_item.details ->> 'researchSourceId' is distinct from target_research_item_id::text then
      continue;
    end if;

    if source_item.category in ('flight', 'train') then
      segment_index := case
        when canonical_item.details ->> 'segmentIndex' ~ '^\d+$'
          then (canonical_item.details ->> 'segmentIndex')::integer
        else 0
      end;
      select entry.value into source_segment
      from jsonb_array_elements(source_item.segments) with ordinality entry(value, position)
      where entry.position = segment_index + 1;
      if source_segment is null then
        raise exception 'RESEARCH_TARGET_CONFLICT' using errcode = '22023';
      end if;
      next_details := jsonb_strip_nulls(jsonb_build_object(
        'mode', source_item.category,
        'origin', source_segment ->> 'origin',
        'destination', source_segment ->> 'destination',
        'departureDate', source_segment ->> 'departureDate',
        'arrivalDate', source_segment ->> 'arrivalDate',
        'arrivalTime', source_segment ->> 'arrivalTime',
        'serviceNumber', source_segment ->> 'serviceNumber',
        'originPlaceId', case when segment_index = 0
          then source_item.origin_place_id else source_item.destination_place_id end,
        'destinationPlaceId', case when segment_index = 0
          then source_item.destination_place_id else source_item.origin_place_id end,
        'researchSourceId', source_item.id,
        'segmentIndex', segment_index
      ));
      update public.itinerary_items item set
        type = 'transport',
        place_id = null,
        notes = source_item.note,
        booking_url = source_item.source_url,
        schedule_text = null,
        details = next_details
      where item.id = canonical_item.id
      returning * into canonical_item;
    elsif source_item.category = 'stay' then
      next_details := jsonb_strip_nulls(jsonb_build_object(
        'address', source_item.location_text,
        'checkInDate', source_item.start_date,
        'checkOutDate', source_item.end_date,
        'researchSourceId', source_item.id
      ));
      update public.itinerary_items item set
        type = 'hotel',
        start_time = null,
        end_time = null,
        schedule_kind = 'none',
        schedule_text = null,
        place_id = source_item.location_place_id,
        notes = source_item.note,
        booking_url = source_item.source_url,
        details = next_details
      where item.id = canonical_item.id
      returning * into canonical_item;
    elsif source_item.category = 'rental' then
      next_details := jsonb_strip_nulls(jsonb_build_object(
        'action', canonical_item.details ->> 'action',
        'address', case canonical_item.details ->> 'action'
          when 'pickup' then source_item.origin_text
          else coalesce(source_item.destination_text, source_item.origin_text) end,
        'provider', coalesce(nullif(source_item.title, ''), nullif(source_item.note, '')),
        'researchSourceId', source_item.id
      ));
      update public.itinerary_items item set
        type = 'car_rental',
        end_time = null,
        schedule_text = null,
        notes = source_item.note,
        booking_url = source_item.source_url,
        details = next_details
      where item.id = canonical_item.id
      returning * into canonical_item;
    end if;

    before_values := case when operation ->> 'kind' = 'update_item'
      then prior_items -> (operation ->> 'entityId') else null end;
    if operation ->> 'kind' = 'update_item' and before_values is null then
      before_values := operation -> 'before';
    end if;
    after_values := public.research_owned_item_snapshot(canonical_item);
    operation := jsonb_set(operation, '{before}', coalesce(before_values, 'null'::jsonb), true);
    operation := jsonb_set(operation, '{after}', after_values, true);
    patched_operations := jsonb_set(
      patched_operations,
      array[operation_index::text],
      operation,
      false
    );
  end loop;

  update public.research_plan_applications application
  set operations = patched_operations,
      before_snapshot = (
        select coalesce(jsonb_agg(
          coalesce(entry.value -> 'before', 'null'::jsonb) order by entry.ordinality
        ), '[]'::jsonb)
        from jsonb_array_elements(patched_operations) with ordinality entry(value, ordinality)
      ),
      after_snapshot = (
        select coalesce(jsonb_agg(
          coalesce(entry.value -> 'after', 'null'::jsonb) order by entry.ordinality
        ), '[]'::jsonb)
        from jsonb_array_elements(patched_operations) with ordinality entry(value, ordinality)
      ),
      applied_at = clock_timestamp()
  where application.id = application_id
  returning * into saved_application;

  return apply_result || jsonb_build_object('appliedAt', saved_application.applied_at);
end;
$$;

comment on function public.apply_research_item_to_variant_v2(uuid, uuid, uuid, uuid, text) is
  'Current atomic Apply boundary. Replaces the complete canonical booking field set, clears absent optional values, stores one price anchor, and records a conflict-safe full before/after field set.';

alter function public.revert_research_plan_application(uuid, uuid)
  rename to revert_research_plan_application_phase_6b_complete_price;

create function public.revert_research_plan_application(
  target_trip_id uuid,
  target_application_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  application_row public.research_plan_applications%rowtype;
  revert_result jsonb;
  operation jsonb;
  before_values jsonb;
  after_values jsonb;
  current_item public.itinerary_items%rowtype;
  full_operations jsonb;
  internal_operations jsonb;
  conflicts jsonb := '[]'::jsonb;
  operation_index integer;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  perform 1 from public.trips trip
  where trip.id = target_trip_id and trip.owner_id = current_user_id for update;
  if not found then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;
  select * into application_row from public.research_plan_applications application
  where application.id = target_application_id and application.trip_id = target_trip_id
  for update;
  if application_row.id is null then
    raise exception 'RESEARCH_APPLICATION_NOT_FOUND' using errcode = '22023';
  end if;
  if application_row.status = 'reverted' then
    return jsonb_build_object(
      'applicationId', application_row.id,
      'status', 'reverted',
      'revertedAt', application_row.reverted_at
    );
  end if;

  full_operations := application_row.operations;
  internal_operations := full_operations;
  for operation_index in 0..jsonb_array_length(full_operations) - 1 loop
    operation := full_operations -> operation_index;
    if operation ->> 'kind' <> 'update_item' then
      continue;
    end if;
    after_values := operation -> 'after';
    select * into current_item from public.itinerary_items item
    where item.id = (operation ->> 'entityId')::uuid
      and item.trip_id = target_trip_id
      and item.variant_id = application_row.route_variant_id
    for update;
    if current_item.id is not null and (
      (after_values ? 'schedule_kind'
        and to_jsonb(current_item.schedule_kind) is distinct from after_values -> 'schedule_kind')
      or (after_values ? 'schedule_text'
        and coalesce(to_jsonb(current_item.schedule_text), 'null'::jsonb)
          is distinct from after_values -> 'schedule_text')
    ) then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'entityId', current_item.id,
        'kind', 'update_item',
        'safeFields', '[]'::jsonb,
        'changedFields', jsonb_build_array('schedule')
      ));
    end if;
    -- The previous Revert implementation restores schedule_kind without
    -- schedule_text. Remove both temporarily, then restore them atomically.
    operation := operation
      #- '{before,schedule_kind}' #- '{before,schedule_text}'
      #- '{after,schedule_kind}' #- '{after,schedule_text}';
    internal_operations := jsonb_set(
      internal_operations,
      array[operation_index::text],
      operation,
      false
    );
  end loop;
  if jsonb_array_length(conflicts) > 0 then
    return jsonb_build_object(
      'applicationId', application_row.id,
      'status', 'conflict',
      'conflicts', conflicts
    );
  end if;

  update public.research_plan_applications application
  set operations = internal_operations,
      before_snapshot = (
        select coalesce(jsonb_agg(
          coalesce(entry.value -> 'before', 'null'::jsonb) order by entry.ordinality
        ), '[]'::jsonb)
        from jsonb_array_elements(internal_operations) with ordinality entry(value, ordinality)
      ),
      after_snapshot = (
        select coalesce(jsonb_agg(
          coalesce(entry.value -> 'after', 'null'::jsonb) order by entry.ordinality
        ), '[]'::jsonb)
        from jsonb_array_elements(internal_operations) with ordinality entry(value, ordinality)
      )
  where application.id = application_row.id;

  revert_result := public.revert_research_plan_application_phase_6b_complete_price(
    target_trip_id,
    target_application_id
  );
  update public.research_plan_applications application
  set operations = full_operations,
      before_snapshot = application_row.before_snapshot,
      after_snapshot = application_row.after_snapshot
  where application.id = application_row.id;
  if revert_result ->> 'status' <> 'reverted' then
    return revert_result;
  end if;

  for operation in
    select value from jsonb_array_elements(application_row.operations)
    where value ->> 'kind' = 'update_item'
  loop
    before_values := operation -> 'before';
    update public.itinerary_items item set
      type = case when before_values ? 'type'
        then (before_values ->> 'type')::public.itinerary_item_type else item.type end,
      notes = case when before_values ? 'notes'
        then nullif(before_values ->> 'notes', '') else item.notes end,
      schedule_kind = case when before_values ? 'schedule_kind'
        then (before_values ->> 'schedule_kind')::public.itinerary_schedule_kind
        else item.schedule_kind end,
      schedule_text = case when before_values ? 'schedule_text'
        then nullif(before_values ->> 'schedule_text', '') else item.schedule_text end
    where item.id = (operation ->> 'entityId')::uuid
      and item.trip_id = target_trip_id
      and item.variant_id = application_row.route_variant_id;
  end loop;
  return revert_result;
end;
$$;

comment on function public.revert_research_plan_application(uuid, uuid) is
  'Conflict-safe durable Revert for complete canonical booking fields, prices, and Apply-owned schedule changes.';

-- Source: supabase/migrations/20260811181150_distribute_stay_costs_and_capture_links.sql
-- Preserve full contextual Plan captures and allocate a Stay total across its
-- canonical nightly Hotel rows. Source prices remain in their captured
-- currency; display conversion is derived outside canonical storage.

set lock_timeout = '5s';

set statement_timeout = '30s';

alter table public.research_items
  add column links jsonb not null default '[]'::jsonb,
  add constraint research_items_links_array
    check (jsonb_typeof(links) = 'array');

comment on column public.research_items.links is
  'Ordered provider-neutral link snapshots copied from a Plan item or saved with Research.';

drop index if exists public.itinerary_items_one_price_per_research_booking;

comment on column public.itinerary_items.price_amount is
  'Canonical Plan cost contribution. Stay totals are allocated across nightly Hotel rows; other multi-item bookings retain one intentional anchor.';

comment on column public.itinerary_items.price_currency is
  'Original ISO 4217 currency for price_amount. Trip-currency conversion is derived with dated reference rates.';

alter function public.apply_research_item_to_variant_v2(uuid, uuid, uuid, uuid, text)
  rename to apply_research_item_to_variant_v2_phase_6b_complete_fields;

create function public.apply_research_item_to_variant_v2(
  target_trip_id uuid,
  target_variant_id uuid,
  target_research_item_id uuid,
  target_item_id uuid default null,
  schedule_choice text default 'automatic'
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  source_item public.research_items%rowtype;
  saved_application public.research_plan_applications%rowtype;
  canonical_item public.itinerary_items%rowtype;
  apply_result jsonb;
  application_id uuid;
  patched_operations jsonb;
  operation jsonb;
  hotel_operation record;
  total_cents bigint;
  base_cents bigint;
  remainder_cents bigint;
  nightly_cents bigint;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  perform 1 from public.trips trip
  where trip.id = target_trip_id and trip.owner_id = current_user_id for update;
  if not found then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;
  select * into source_item from public.research_items item
  where item.id = target_research_item_id and item.trip_id = target_trip_id for update;
  if source_item.id is null then
    raise exception 'RESEARCH_ITEM_NOT_FOUND' using errcode = '22023';
  end if;

  -- A clean application created by the previous one-anchor behavior must pass
  -- through Apply once more so every nightly row receives its share.
  if source_item.category = 'stay' then
    update public.research_plan_applications application
    set status = 'superseded', superseded_at = clock_timestamp()
    where application.trip_id = target_trip_id
      and application.route_variant_id = target_variant_id
      and application.source_research_item_id = target_research_item_id
      and application.status = 'applied'
      and (
        select count(*)
        from jsonb_array_elements(application.operations) entry(value)
        where entry.value ->> 'kind' in ('create_item', 'update_item')
          and entry.value -> 'after' ->> 'type' = 'hotel'
      ) > 1
      and (
        select count(*)
        from jsonb_array_elements(application.operations) entry(value)
        where entry.value ->> 'kind' in ('create_item', 'update_item')
          and entry.value -> 'after' ->> 'type' = 'hotel'
          and entry.value -> 'after' -> 'price_amount' <> 'null'::jsonb
      ) < (
        select count(*)
        from jsonb_array_elements(application.operations) entry(value)
        where entry.value ->> 'kind' in ('create_item', 'update_item')
          and entry.value -> 'after' ->> 'type' = 'hotel'
      );
  end if;

  apply_result := public.apply_research_item_to_variant_v2_phase_6b_complete_fields(
    target_trip_id,
    target_variant_id,
    target_research_item_id,
    target_item_id,
    schedule_choice
  );
  if coalesce((apply_result ->> 'idempotent')::boolean, false)
    or source_item.category <> 'stay' then
    return apply_result;
  end if;

  application_id := (apply_result ->> 'applicationId')::uuid;
  select * into saved_application
  from public.research_plan_applications application
  where application.id = application_id for update;
  patched_operations := saved_application.operations;
  total_cents := round(source_item.total_price_amount * 100)::bigint;

  for hotel_operation in
    select
      entry.ordinality - 1 as operation_index,
      item.id,
      row_number() over (order by day.date nulls last, day.day_number, item.id) as price_position,
      count(*) over () as hotel_count
    from jsonb_array_elements(patched_operations) with ordinality entry(value, ordinality)
    join public.itinerary_items item on item.id = (entry.value ->> 'entityId')::uuid
    join public.trip_days day on day.id = item.day_id and day.variant_id = target_variant_id
    where entry.value ->> 'kind' in ('create_item', 'update_item')
      and item.trip_id = target_trip_id
      and item.variant_id = target_variant_id
      and item.type = 'hotel'
      and item.details ->> 'researchSourceId' = target_research_item_id::text
  loop
    base_cents := total_cents / hotel_operation.hotel_count;
    remainder_cents := total_cents % hotel_operation.hotel_count;
    nightly_cents := base_cents + case
      when hotel_operation.price_position <= remainder_cents then 1 else 0 end;
    update public.itinerary_items item
    set price_amount = nightly_cents::numeric / 100,
        price_currency = source_item.currency
    where item.id = hotel_operation.id
    returning * into canonical_item;

    operation := patched_operations -> hotel_operation.operation_index::integer;
    operation := jsonb_set(
      operation,
      '{after}',
      public.research_owned_item_snapshot(canonical_item),
      true
    );
    patched_operations := jsonb_set(
      patched_operations,
      array[hotel_operation.operation_index::text],
      operation,
      false
    );
  end loop;

  update public.research_plan_applications application
  set operations = patched_operations,
      after_snapshot = (
        select coalesce(jsonb_agg(
          coalesce(entry.value -> 'after', 'null'::jsonb) order by entry.ordinality
        ), '[]'::jsonb)
        from jsonb_array_elements(patched_operations) with ordinality entry(value, ordinality)
      ),
      applied_at = clock_timestamp()
  where application.id = application_id
  returning * into saved_application;

  return apply_result || jsonb_build_object('appliedAt', saved_application.applied_at);
end;
$$;

comment on function public.apply_research_item_to_variant_v2(uuid, uuid, uuid, uuid, text) is
  'Atomic current Apply boundary. Replaces complete booking fields, allocates Stay totals exactly across nightly Hotel rows, and records conflict-safe history.';

-- Source: supabase/migrations/20260811185219_expire_research_apply_after_plan_change.sql
-- Applied is a one-time snapshot of the Plan produced by Apply. It remains
-- current only while every owned canonical value and every booking date still
-- maps to the same Plan structure. History remains durable and reusable.

set lock_timeout = '5s';

set statement_timeout = '30s';

create or replace function public.research_application_matches_current(
  target_application_id uuid
) returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  application_row public.research_plan_applications%rowtype;
  source_item public.research_items%rowtype;
  operation jsonb;
  current_values jsonb;
  entity_id uuid;
  required_start date;
  required_end date;
begin
  select * into application_row
  from public.research_plan_applications application
  where application.id = target_application_id;
  if application_row.id is null or application_row.status <> 'applied' then
    return false;
  end if;

  select * into source_item
  from public.research_items item
  where item.id = application_row.source_research_item_id
    and item.trip_id = application_row.trip_id;
  if source_item.id is null then
    return false;
  end if;

  for operation in
    select value from jsonb_array_elements(application_row.operations)
  loop
    entity_id := (operation ->> 'entityId')::uuid;
    current_values := null;
    case operation ->> 'kind'
      when 'create_item', 'update_item' then
        select to_jsonb(item) into current_values
        from public.itinerary_items item
        where item.id = entity_id
          and item.trip_id = application_row.trip_id
          and item.variant_id = application_row.route_variant_id;
      when 'create_day', 'update_day' then
        select to_jsonb(day) into current_values
        from public.trip_days day
        where day.id = entity_id
          and day.variant_id = application_row.route_variant_id;
      when 'delete_day' then
        if exists (select 1 from public.trip_days day where day.id = entity_id) then
          return false;
        end if;
        continue;
      when 'update_trip' then
        select to_jsonb(trip) into current_values
        from public.trips trip
        where trip.id = entity_id;
      else
        return false;
    end case;
    if current_values is null or exists (
      select 1
      from jsonb_each(operation -> 'after') expected
      where current_values -> expected.key is distinct from expected.value
    ) then
      return false;
    end if;
  end loop;

  -- Derive the complete booking envelope, including overnight journey dates.
  select min(candidate_date), max(candidate_date)
  into required_start, required_end
  from (
    select source_item.start_date as candidate_date
    union all select source_item.end_date
    union all
    select case when segment.value ->> 'departureDate' ~ '^\d{4}-\d{2}-\d{2}$'
      then (segment.value ->> 'departureDate')::date end
    from jsonb_array_elements(coalesce(source_item.segments, '[]'::jsonb)) segment(value)
    union all
    select case when segment.value ->> 'arrivalDate' ~ '^\d{4}-\d{2}-\d{2}$'
      then (segment.value ->> 'arrivalDate')::date end
    from jsonb_array_elements(coalesce(source_item.segments, '[]'::jsonb)) segment(value)
  ) dates
  where candidate_date is not null;
  if required_start is null or required_end is null then
    return false;
  end if;

  -- Apply creates/reconciles a continuous dated Plan through the booking end.
  -- Removing checkout/return/arrival (or any intervening Day) expires Applied.
  if exists (
    select 1
    from generate_series(required_start, required_end, interval '1 day') expected(date)
    where not exists (
      select 1 from public.trip_days day
      where day.variant_id = application_row.route_variant_id
        and day.date = expected.date::date
    )
  ) then
    return false;
  end if;

  -- A stable item ID is not sufficient when its Day was re-dated. Each
  -- canonical booking row must still sit on its Research-owned date.
  if exists (
    select 1
    from jsonb_array_elements(application_row.operations) entry(value)
    join public.itinerary_items item
      on item.id = (entry.value ->> 'entityId')::uuid
     and item.trip_id = application_row.trip_id
     and item.variant_id = application_row.route_variant_id
    join public.trip_days day
      on day.id = item.day_id
     and day.variant_id = application_row.route_variant_id
    where entry.value ->> 'kind' in ('create_item', 'update_item')
      and item.details ->> 'researchSourceId' = source_item.id::text
      and case source_item.category
        when 'flight' then day.date is distinct from case
          when item.details ->> 'departureDate' ~ '^\d{4}-\d{2}-\d{2}$'
            then (item.details ->> 'departureDate')::date end
        when 'train' then day.date is distinct from case
          when item.details ->> 'departureDate' ~ '^\d{4}-\d{2}-\d{2}$'
            then (item.details ->> 'departureDate')::date end
        when 'stay' then day.date < source_item.start_date
          or day.date >= source_item.end_date
        when 'rental' then day.date is distinct from case item.details ->> 'action'
          when 'pickup' then source_item.start_date
          when 'return' then source_item.end_date
          else null end
        else true
      end
  ) then
    return false;
  end if;

  -- A Stay additionally requires one Apply-owned Hotel row for every night;
  -- its checkout Day is covered by the complete envelope check above.
  if source_item.category = 'stay' and exists (
    select 1
    from generate_series(
      source_item.start_date,
      source_item.end_date - 1,
      interval '1 day'
    ) expected(night)
    where not exists (
      select 1
      from jsonb_array_elements(application_row.operations) entry(value)
      join public.itinerary_items item
        on item.id = (entry.value ->> 'entityId')::uuid
       and item.trip_id = application_row.trip_id
       and item.variant_id = application_row.route_variant_id
      join public.trip_days day on day.id = item.day_id
      where entry.value ->> 'kind' in ('create_item', 'update_item')
        and item.type = 'hotel'
        and item.details ->> 'researchSourceId' = source_item.id::text
        and day.date = expected.night::date
    )
  ) then
    return false;
  end if;

  if exists (
    select 1
    from public.itinerary_items item
    where item.trip_id = application_row.trip_id
      and item.variant_id = application_row.route_variant_id
      and item.details ->> 'researchSourceId' = source_item.id::text
      and not exists (
        select 1
        from jsonb_array_elements(application_row.operations) entry(value)
        where entry.value ->> 'kind' in ('create_item', 'update_item')
          and entry.value ->> 'entityId' = item.id::text
      )
  ) then
    return false;
  end if;

  return true;
end;
$$;

comment on function public.research_application_matches_current(uuid) is
  'True only while an Apply one-time snapshot still exactly matches its canonical booking fields, entities, and complete Plan date span.';

-- Source: supabase/migrations/20260811190356_ensure_stay_apply_restores_checkout_day.sql
-- A Stay occupies its checkout boundary in the Plan schedule even though it
-- creates Hotel rows only for the intervening nights. Restore that boundary
-- during Apply and include it in the same durable, reversible change set.

set lock_timeout = '5s';

set statement_timeout = '30s';

alter function public.apply_research_item_to_variant_v2(uuid, uuid, uuid, uuid, text)
  rename to apply_research_item_to_variant_v2_phase_6b_nightly_costs;

create function public.apply_research_item_to_variant_v2(
  target_trip_id uuid,
  target_variant_id uuid,
  target_research_item_id uuid,
  target_item_id uuid default null,
  schedule_choice text default 'automatic'
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  source_item public.research_items%rowtype;
  target_variant public.route_variants%rowtype;
  saved_application public.research_plan_applications%rowtype;
  created_day public.trip_days%rowtype;
  trip_before jsonb;
  trip_after jsonb;
  day_after jsonb;
  day_operation jsonb;
  trip_operation jsonb;
  patched_operations jsonb;
  apply_result jsonb;
  application_id uuid;
  current_count integer;
  dated_count integer;
  plan_start date;
  plan_end date;
  has_trip_operation boolean;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;

  perform 1
  from public.trips trip
  where trip.id = target_trip_id
    and trip.owner_id = current_user_id
  for update;
  if not found then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;

  select * into target_variant
  from public.route_variants variant
  where variant.id = target_variant_id
    and variant.trip_id = target_trip_id
  for update;
  if target_variant.id is null then
    raise exception 'VARIANT_NOT_FOUND' using errcode = '22023';
  end if;

  select * into source_item
  from public.research_items item
  where item.id = target_research_item_id
    and item.trip_id = target_trip_id
  for update;
  if source_item.id is null then
    raise exception 'RESEARCH_ITEM_NOT_FOUND' using errcode = '22023';
  end if;

  apply_result := public.apply_research_item_to_variant_v2_phase_6b_nightly_costs(
    target_trip_id,
    target_variant_id,
    target_research_item_id,
    target_item_id,
    schedule_choice
  );

  if coalesce((apply_result ->> 'idempotent')::boolean, false)
    or source_item.category <> 'stay'
    or source_item.end_date is null
    or exists (
      select 1
      from public.trip_days day
      where day.variant_id = target_variant_id
        and day.date = source_item.end_date
    ) then
    return apply_result;
  end if;

  select count(*)::integer, count(day.date)::integer, min(day.date), max(day.date)
  into current_count, dated_count, plan_start, plan_end
  from public.trip_days day
  where day.variant_id = target_variant_id;

  -- The underlying Stay Apply already covers every night through checkout - 1.
  -- A different gap means the Plan is not safe to repair automatically.
  if current_count < 1
    or dated_count <> current_count
    or source_item.end_date <> plan_end + 1 then
    raise exception 'RESEARCH_IMPACT_MANUAL_REVIEW' using errcode = '22023';
  end if;
  if current_count >= 366 then
    raise exception 'RESEARCH_PLAN_DAY_LIMIT' using errcode = '22023';
  end if;

  if target_variant.is_primary then
    select jsonb_build_object(
      'start_date', trip.start_date,
      'end_date', trip.end_date,
      'day_count', trip.day_count
    )
    into trip_before
    from public.trips trip
    where trip.id = target_trip_id;
  end if;

  insert into public.trip_days (variant_id, day_number, date)
  values (target_variant_id, current_count + 1, source_item.end_date)
  returning * into created_day;

  day_after := jsonb_build_object(
    'variant_id', created_day.variant_id,
    'day_number', created_day.day_number,
    'date', created_day.date,
    'title', created_day.title,
    'notes', created_day.notes
  );
  day_operation := jsonb_build_object(
    'kind', 'create_day',
    'entityId', created_day.id,
    'before', null,
    'after', day_after
  );

  if target_variant.is_primary then
    update public.trips trip
    set start_date = plan_start,
        end_date = source_item.end_date,
        day_count = current_count + 1
    where trip.id = target_trip_id;

    trip_after := jsonb_build_object(
      'start_date', plan_start,
      'end_date', source_item.end_date,
      'day_count', current_count + 1
    );
  end if;

  application_id := (apply_result ->> 'applicationId')::uuid;
  select * into saved_application
  from public.research_plan_applications application
  where application.id = application_id
    and application.trip_id = target_trip_id
    and application.route_variant_id = target_variant_id
  for update;
  if saved_application.id is null then
    raise exception 'RESEARCH_APPLICATION_NOT_FOUND' using errcode = '22023';
  end if;

  patched_operations := saved_application.operations || jsonb_build_array(day_operation);

  if target_variant.is_primary then
    select exists (
      select 1
      from jsonb_array_elements(patched_operations) entry(value)
      where entry.value ->> 'kind' = 'update_trip'
        and entry.value ->> 'entityId' = target_trip_id::text
    ) into has_trip_operation;

    if has_trip_operation then
      select jsonb_agg(
        case
          when entry.value ->> 'kind' = 'update_trip'
            and entry.value ->> 'entityId' = target_trip_id::text
          then jsonb_set(entry.value, '{after}', trip_after, true)
          else entry.value
        end
        order by entry.ordinality
      )
      into patched_operations
      from jsonb_array_elements(patched_operations)
        with ordinality entry(value, ordinality);
    else
      trip_operation := jsonb_build_object(
        'kind', 'update_trip',
        'entityId', target_trip_id,
        'before', trip_before,
        'after', trip_after
      );
      patched_operations := patched_operations || jsonb_build_array(trip_operation);
    end if;
  end if;

  update public.research_plan_applications application
  set affected_entity_ids = array_append(application.affected_entity_ids, created_day.id),
      operations = patched_operations,
      before_snapshot = (
        select coalesce(jsonb_agg(
          coalesce(entry.value -> 'before', 'null'::jsonb)
          order by entry.ordinality
        ), '[]'::jsonb)
        from jsonb_array_elements(patched_operations)
          with ordinality entry(value, ordinality)
      ),
      after_snapshot = (
        select coalesce(jsonb_agg(
          coalesce(entry.value -> 'after', 'null'::jsonb)
          order by entry.ordinality
        ), '[]'::jsonb)
        from jsonb_array_elements(patched_operations)
          with ordinality entry(value, ordinality)
      ),
      applied_at = clock_timestamp()
  where application.id = application_id
  returning * into saved_application;

  return apply_result || jsonb_build_object(
    'affectedEntityIds', saved_application.affected_entity_ids,
    'appliedAt', saved_application.applied_at
  );
end;
$$;

comment on function public.apply_research_item_to_variant_v2(uuid, uuid, uuid, uuid, text) is
  'Atomic current Apply boundary. A Stay restores its checkout Day, distributes nightly cost, and records every canonical and schedule change for conflict-safe Revert.';

-- Source: supabase/migrations/20260812183629_public_share_themes_and_place_photos.sql
-- Add opt-in Google Place photo IDs without changing any deployed Phase 6A
-- response shape. Old management RPCs and get_public_itinerary_v2 remain
-- callable; current clients use the additive versioned functions below.

alter table public.public_itinerary_links
  add column show_place_photos boolean not null default false;

create function public.create_public_itinerary_link_v2(
  target_variant_id uuid,
  requested_default_view public.public_itinerary_view default 'overview',
  requested_show_times boolean default true,
  requested_show_map_routes boolean default true,
  requested_allow_route_explore boolean default true,
  requested_show_addresses boolean default false,
  requested_show_notes boolean default false,
  requested_show_quick_action_links boolean default true,
  requested_show_place_photos boolean default false,
  requested_share_title text default null,
  requested_share_description text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  legacy_result jsonb;
  managed_link public.public_itinerary_links%rowtype;
begin
  legacy_result := public.create_public_itinerary_link(
    target_variant_id,
    requested_default_view,
    requested_show_times,
    requested_show_map_routes,
    requested_allow_route_explore,
    requested_show_addresses,
    requested_show_notes,
    requested_show_quick_action_links,
    requested_share_title,
    requested_share_description
  );

  update public.public_itinerary_links link
  set show_place_photos = requested_show_place_photos
  where link.id = (legacy_result ->> 'id')::uuid
    and link.created_by = app_private.app_current_user_id()
    and link.revoked_at is null
  returning link.* into managed_link;

  if managed_link.id is null then
    raise exception 'PUBLIC_LINK_OWNER_REQUIRED' using errcode = '42501';
  end if;

  return legacy_result || jsonb_build_object(
    'showPlacePhotos', managed_link.show_place_photos,
    'updatedAt', managed_link.updated_at
  );
end;
$$;

