  );
$$;

create or replace function public.public_share_page_image_v1(shared_token uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (
      select public.public_share_image_manifest_v1(export.permanent_slug)
      from public.public_itinerary_links page
      join public.share_image_exports export on export.share_page_id = page.id
      where page.public_token = shared_token
        and page.revoked_at is null
        and page.allow_long_image_download
        and export.revoked_at is null
        and export.expires_at > now()
        and export.current_version_id is not null
      order by export.created_at desc
      limit 1
    ),
    '{"available":false}'::jsonb
  );
$$;

create or replace function public.owner_share_page_image_state_v1(target_share_page_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (
      select jsonb_build_object(
        'exportId', export.id,
        'permanentSlug', export.permanent_slug,
        'versionNumber', version.version_number,
        'sourceSnapshotHash', version.source_snapshot_hash,
        'renderConfig', version.render_config,
        'partCount', (select count(*) from public.share_image_parts part
          where part.version_id = version.id),
        'createdAt', export.created_at,
        'updatedAt', export.updated_at,
        'expiresAt', export.expires_at
      )
      from public.public_itinerary_links page
      join public.share_image_exports export on export.share_page_id = page.id
      join public.share_image_versions version on version.id = export.current_version_id
      where page.id = target_share_page_id
        and page.created_by = app_private.app_current_user_id()
        and page.revoked_at is null
        and export.revoked_at is null
        and export.expires_at > now()
      order by export.created_at desc
      limit 1
    ),
    'null'::jsonb
  );
$$;

-- Source: supabase/migrations/20260816191530_add_traverse_public_template.sql
-- Publish Traverse and make Ethereal the default for newly created share pages.
-- Persisted template ids remain unchanged so every existing link keeps its design.

alter table public.public_itinerary_links
  alter column template_id set default 'ethereal',
  alter column template_version set default 1;

create or replace function public.create_share_page_v1(
  target_variant_id uuid,
  requested_default_view public.public_itinerary_view default 'timeline',
  requested_show_times boolean default true,
  requested_show_map_routes boolean default true,
  requested_allow_route_explore boolean default true,
  requested_show_addresses boolean default true,
  requested_show_notes boolean default true,
  requested_show_quick_action_links boolean default true,
  requested_show_place_photos boolean default true,
  requested_share_title text default null,
  requested_share_description text default null,
  requested_template_id text default 'ethereal',
  requested_template_version integer default 1,
  requested_allow_long_image_download boolean default true,
  requested_long_image_qr_destination text default 'current_share_page',
  requested_long_image_qr_share_page_id uuid default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  target_trip_id uuid;
  managed_link public.public_itinerary_links%rowtype;
  projection jsonb;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  if not (
    (requested_template_id = 'standard' and requested_template_version = 1)
    or (requested_template_id = 'bento' and requested_template_version in (1, 2))
    or (requested_template_id = 'ethereal' and requested_template_version = 1)
    or (requested_template_id = 'journal' and requested_template_version = 1)
    or (requested_template_id = 'traverse' and requested_template_version = 1)
  ) then
    raise exception 'PUBLIC_TEMPLATE_UNAVAILABLE' using errcode = '22023';
  end if;
  if requested_long_image_qr_destination not in (
    'current_share_page', 'share_page', 'homepage'
  ) then
    raise exception 'PUBLIC_IMAGE_QR_DESTINATION_INVALID' using errcode = '22023';
  end if;

  select variant.trip_id into target_trip_id
  from public.route_variants variant
  join public.trips trip on trip.id = variant.trip_id
  where variant.id = target_variant_id and trip.owner_id = current_user_id;
  if target_trip_id is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;
  if requested_long_image_qr_destination = 'share_page' and not exists (
    select 1 from public.public_itinerary_links destination
    where destination.id = requested_long_image_qr_share_page_id
      and destination.created_by = current_user_id
      and destination.revoked_at is null
  ) then
    raise exception 'PUBLIC_IMAGE_QR_SHARE_PAGE_INVALID' using errcode = '22023';
  end if;

  insert into public.public_itinerary_links (
    trip_id, variant_id, created_by, default_view, show_times,
    show_map_routes, allow_route_explore, show_addresses, show_notes,
    show_quick_action_links, show_place_photos, share_title,
    share_description, template_id, template_version,
    allow_long_image_download, long_image_qr_destination,
    long_image_qr_share_page_id
  ) values (
    target_trip_id, target_variant_id, current_user_id, requested_default_view,
    requested_show_times, requested_show_map_routes, requested_allow_route_explore,
    requested_show_addresses, requested_show_notes,
    requested_show_quick_action_links, requested_show_place_photos,
    nullif(btrim(requested_share_title), ''),
    nullif(btrim(requested_share_description), ''), requested_template_id,
    requested_template_version, requested_allow_long_image_download,
    requested_long_image_qr_destination,
    case when requested_long_image_qr_destination = 'share_page'
      then requested_long_image_qr_share_page_id else null end
  ) returning * into managed_link;

  projection := public.get_public_itinerary_v4(managed_link.public_token);
  if not projection @> '{"available":true}'::jsonb then
    raise exception 'PUBLIC_SHARE_PAGE_SNAPSHOT_FAILED' using errcode = 'P0001';
  end if;
  update public.public_itinerary_links
  set
    published_snapshot = projection,
    snapshot_hash = encode(extensions.digest(projection::text, 'sha256'), 'hex'),
    published_at = now()
  where id = managed_link.id
  returning * into managed_link;
  return public.public_share_page_owner_json(managed_link);
end;
$$;

create or replace function public.update_share_page_v1(
  target_share_page_id uuid,
  requested_default_view public.public_itinerary_view,
  requested_show_times boolean,
  requested_show_map_routes boolean,
  requested_allow_route_explore boolean,
  requested_show_addresses boolean,
  requested_show_notes boolean,
  requested_show_quick_action_links boolean,
  requested_show_place_photos boolean,
  requested_share_title text,
  requested_share_description text,
  requested_template_id text,
  requested_template_version integer,
  requested_allow_long_image_download boolean,
  requested_long_image_qr_destination text,
  requested_long_image_qr_share_page_id uuid default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  managed_link public.public_itinerary_links%rowtype;
  projection jsonb;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  if not (
    (requested_template_id = 'standard' and requested_template_version = 1)
    or (requested_template_id = 'bento' and requested_template_version in (1, 2))
    or (requested_template_id = 'ethereal' and requested_template_version = 1)
    or (requested_template_id = 'journal' and requested_template_version = 1)
    or (requested_template_id = 'traverse' and requested_template_version = 1)
  ) then
    raise exception 'PUBLIC_TEMPLATE_UNAVAILABLE' using errcode = '22023';
  end if;
  if requested_long_image_qr_destination not in (
    'current_share_page', 'share_page', 'homepage'
  ) then
    raise exception 'PUBLIC_IMAGE_QR_DESTINATION_INVALID' using errcode = '22023';
  end if;
  if requested_long_image_qr_destination = 'share_page' and not exists (
    select 1 from public.public_itinerary_links destination
    where destination.id = requested_long_image_qr_share_page_id
      and destination.created_by = current_user_id
      and destination.revoked_at is null
  ) then
    raise exception 'PUBLIC_IMAGE_QR_SHARE_PAGE_INVALID' using errcode = '22023';
  end if;

  update public.public_itinerary_links link
  set
    default_view = requested_default_view,
    show_times = requested_show_times,
    show_map_routes = requested_show_map_routes,
    allow_route_explore = requested_allow_route_explore,
    show_addresses = requested_show_addresses,
    show_notes = requested_show_notes,
    show_quick_action_links = requested_show_quick_action_links,
    show_place_photos = requested_show_place_photos,
    share_title = nullif(btrim(requested_share_title), ''),
    share_description = nullif(btrim(requested_share_description), ''),
    template_id = requested_template_id,
    template_version = requested_template_version,
    allow_long_image_download = requested_allow_long_image_download,
    long_image_qr_destination = requested_long_image_qr_destination,
    long_image_qr_share_page_id = case
      when requested_long_image_qr_destination = 'share_page'
        then requested_long_image_qr_share_page_id else null end
  where link.id = target_share_page_id
    and link.created_by = current_user_id
    and link.trip_id is not null
    and link.revoked_at is null
  returning * into managed_link;
  if managed_link.id is null then
    raise exception 'PUBLIC_LINK_OWNER_REQUIRED' using errcode = '42501';
  end if;

  projection := public.get_public_itinerary_v4(managed_link.public_token);
  if not projection @> '{"available":true}'::jsonb then
    raise exception 'PUBLIC_SHARE_PAGE_SNAPSHOT_FAILED' using errcode = 'P0001';
  end if;
  update public.public_itinerary_links
  set
    published_snapshot = projection,
    snapshot_hash = encode(extensions.digest(projection::text, 'sha256'), 'hex'),
    published_at = now()
  where id = managed_link.id
  returning * into managed_link;
  return public.public_share_page_owner_json(managed_link);
end;
$$;

create or replace function public.create_share_page_v2(
  target_variant_id uuid,
  requested_default_view public.public_itinerary_view default 'timeline',
  requested_show_times boolean default true,
  requested_show_map_routes boolean default true,
  requested_allow_route_explore boolean default true,
  requested_show_addresses boolean default true,
  requested_show_notes boolean default true,
  requested_show_quick_action_links boolean default true,
  requested_show_place_photos boolean default true,
  requested_share_title text default null,
  requested_share_description text default null,
  requested_template_id text default 'ethereal',
  requested_template_version integer default 1,
  requested_allow_long_image_download boolean default true,
  requested_long_image_qr_destination text default 'current_share_page',
  requested_long_image_qr_share_page_id uuid default null,
  requested_long_image_start_day_number integer default null,
  requested_long_image_end_day_number integer default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_day_count integer;
  created_page jsonb;
  managed_link public.public_itinerary_links%rowtype;
begin
  select trip.day_count into target_day_count
  from public.route_variants variant
  join public.trips trip on trip.id = variant.trip_id
  where variant.id = target_variant_id and trip.owner_id = app_private.app_current_user_id();

  if target_day_count is null then
    raise exception 'TRIP_OWNER_REQUIRED' using errcode = '42501';
  end if;
  if not (
    (
      requested_long_image_start_day_number is null
      and requested_long_image_end_day_number is null
    )
    or (
      requested_long_image_start_day_number between 1 and target_day_count
      and requested_long_image_end_day_number between
        requested_long_image_start_day_number and target_day_count
    )
  ) then
    raise exception 'PUBLIC_IMAGE_DAY_RANGE_INVALID' using errcode = '22023';
  end if;

  created_page := public.create_share_page_v1(
    target_variant_id => target_variant_id,
    requested_default_view => requested_default_view,
    requested_show_times => requested_show_times,
    requested_show_map_routes => requested_show_map_routes,
    requested_allow_route_explore => requested_allow_route_explore,
    requested_show_addresses => requested_show_addresses,
    requested_show_notes => requested_show_notes,
    requested_show_quick_action_links => requested_show_quick_action_links,
    requested_show_place_photos => requested_show_place_photos,
    requested_share_title => requested_share_title,
    requested_share_description => requested_share_description,
    requested_template_id => requested_template_id,
    requested_template_version => requested_template_version,
    requested_allow_long_image_download => requested_allow_long_image_download,
    requested_long_image_qr_destination => requested_long_image_qr_destination,
    requested_long_image_qr_share_page_id => requested_long_image_qr_share_page_id
  );

  update public.public_itinerary_links link
  set
    long_image_start_day_number = requested_long_image_start_day_number,
    long_image_end_day_number = requested_long_image_end_day_number
  where link.id = (created_page ->> 'id')::uuid
    and link.created_by = app_private.app_current_user_id()
  returning * into managed_link;

  return public.public_share_page_owner_json(managed_link);
end;
$$;

-- Source: supabase/migrations/20260817153403_phase_8a_item_attachments.sql
-- Phase 8A stores owner-scoped itinerary attachments in a private bucket.
-- All writes use the versioned RPCs added by the following migration; the
-- table policies below intentionally expose only owner reads.

create type public.asset_media_kind as enum ('image', 'pdf', 'video');

create type public.asset_status as enum ('pending', 'ready', 'failed', 'deleting');

alter table public.trips
  add constraint trips_id_owner_unique unique (id, owner_id);

alter table public.itinerary_items
  add constraint itinerary_items_id_trip_unique unique (id, trip_id);

alter table public.public_itinerary_links
  add column show_attachments boolean not null default false;

create table public.assets (
  id uuid primary key default gen_random_uuid(),
  owner_id varchar(64) not null,
  storage_provider text not null default 'supabase',
  bucket text not null default 'trip-assets',
  object_key text not null,
  thumbnail_object_key text,
  media_kind public.asset_media_kind not null,
  mime_type text not null,
  byte_size bigint not null,
  sha256 text not null,
  status public.asset_status not null default 'pending',
  width integer,
  height integer,
  duration_seconds numeric(12, 3),
  pending_expires_at timestamptz,
  finalized_at timestamptz,
  failure_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint assets_id_owner_unique unique (id, owner_id),
  constraint assets_object_key_unique unique (object_key),
  constraint assets_thumbnail_object_key_unique unique (thumbnail_object_key),
  constraint assets_storage_provider check (storage_provider = 'supabase'),
  constraint assets_bucket check (bucket = 'trip-assets'),
  constraint assets_object_key_format check (
    object_key ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/original$'
  ),
  constraint assets_thumbnail_key_format check (
    thumbnail_object_key is null
    or thumbnail_object_key ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/(thumbnail|poster)\.webp$'
  ),
  constraint assets_byte_size check (byte_size between 1 and 31457280),
  constraint assets_sha256_format check (sha256 ~ '^[0-9a-f]{64}$'),
  constraint assets_mime_type check (mime_type in (
    'image/jpeg', 'image/png', 'image/webp', 'application/pdf',
    'video/mp4', 'video/webm', 'video/quicktime'
  )),
  constraint assets_dimensions check (
    (width is null and height is null) or (width > 0 and height > 0)
  ),
  constraint assets_duration check (duration_seconds is null or duration_seconds >= 0),
  constraint assets_pending_expiration check (
    (status = 'pending' and pending_expires_at is not null and finalized_at is null)
    or (status <> 'pending' and pending_expires_at is null)
  ),
  constraint assets_ready_state check (
    status <> 'ready' or (finalized_at is not null and failure_reason is null)
  )
);

create unique index assets_owner_ready_blob_unique
  on public.assets (owner_id, sha256, byte_size)
  where status = 'ready';

create index assets_owner_status_idx on public.assets (owner_id, status, created_at);

create index assets_pending_expiration_idx on public.assets (pending_expires_at)
  where status = 'pending';

create table public.asset_links (
  id uuid primary key default gen_random_uuid(),
  asset_id uuid not null,
  owner_id varchar(64) not null,
  trip_id uuid not null,
  itinerary_item_id uuid not null,
  display_filename text not null,
  sort_order integer not null default 0,
  include_in_share boolean not null default false,
  public_ref text not null default encode(extensions.gen_random_bytes(32), 'hex'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint asset_links_asset_owner_fkey foreign key (asset_id, owner_id)
    references public.assets (id, owner_id) on delete cascade,
  constraint asset_links_trip_owner_fkey foreign key (trip_id, owner_id)
    references public.trips (id, owner_id) on delete cascade,
  constraint asset_links_item_trip_fkey foreign key (itinerary_item_id, trip_id)
    references public.itinerary_items (id, trip_id) on delete cascade,
  constraint asset_links_asset_item_unique unique (asset_id, itinerary_item_id),
  constraint asset_links_item_order_unique unique (itinerary_item_id, sort_order),
  constraint asset_links_public_ref_unique unique (public_ref),
  constraint asset_links_filename check (
    char_length(btrim(display_filename)) between 1 and 240
    and display_filename !~ '[[:cntrl:]]'
  ),
  constraint asset_links_sort_order check (sort_order between 0 and 4),
  constraint asset_links_public_ref_format check (public_ref ~ '^[0-9a-f]{64}$')
);

create index asset_links_trip_item_idx
  on public.asset_links (trip_id, itinerary_item_id, sort_order);

create index asset_links_asset_idx on public.asset_links (asset_id);

create index asset_links_public_share_idx
  on public.asset_links (trip_id, itinerary_item_id, public_ref)
  where include_in_share;

create table public.asset_deletion_queue (
  asset_id uuid primary key,
  owner_id varchar(64) not null,
  bucket text not null,
  object_key text not null,
  thumbnail_object_key text,
  attempts integer not null default 0,
  next_attempt_at timestamptz not null default now(),
  last_error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint asset_deletion_queue_attempts check (attempts >= 0),
  constraint asset_deletion_queue_bucket check (bucket = 'trip-assets')
);

create index asset_deletion_queue_retry_idx
  on public.asset_deletion_queue (next_attempt_at, created_at);

create function public.enforce_asset_link_limits()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  linked_size bigint;
  linked_status public.asset_status;
  current_count integer;
  current_bytes bigint;
begin
  perform pg_advisory_xact_lock(hashtextextended(new.itinerary_item_id::text, 801));

  select asset.byte_size, asset.status into linked_size, linked_status
  from public.assets asset
  where asset.id = new.asset_id and asset.owner_id = new.owner_id;
  if linked_status not in ('pending', 'ready') then
    raise exception 'ASSET_NOT_ATTACHABLE' using errcode = '23514';
  end if;

  select count(*), coalesce(sum(asset.byte_size), 0)
  into current_count, current_bytes
  from public.asset_links link
  join public.assets asset on asset.id = link.asset_id
  where link.itinerary_item_id = new.itinerary_item_id
    and link.id <> new.id
    and asset.status in ('pending', 'ready');

  if current_count >= 5 then
    raise exception 'ATTACHMENT_COUNT_LIMIT' using errcode = '23514';
  end if;
  if current_bytes + linked_size > 52428800 then
    raise exception 'ATTACHMENT_ITEM_BYTES_LIMIT' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger asset_links_enforce_limits
before insert or update of asset_id, owner_id, itinerary_item_id
on public.asset_links
for each row execute function public.enforce_asset_link_limits();

create function public.enforce_owner_ready_asset_quota()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  ready_bytes bigint;
begin
  if new.status <> 'ready' or old.status = 'ready' then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text, 802));
  select coalesce(sum(asset.byte_size), 0) into ready_bytes
  from public.assets asset
  where asset.owner_id = new.owner_id
    and asset.status = 'ready'
    and asset.id <> new.id;
  if ready_bytes + new.byte_size > 262144000 then
    raise exception 'ATTACHMENT_OWNER_BYTES_LIMIT' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger assets_enforce_ready_quota
before update of status on public.assets
for each row execute function public.enforce_owner_ready_asset_quota();

create function public.queue_orphan_asset()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  orphan_id uuid := old.asset_id;
begin
  if tg_op = 'UPDATE' and new.asset_id = old.asset_id then return new; end if;
  if exists (select 1 from public.asset_links link where link.asset_id = orphan_id) then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  update public.assets set status = 'deleting', pending_expires_at = null
  where id = orphan_id and status <> 'deleting';
  insert into public.asset_deletion_queue (
    asset_id, owner_id, bucket, object_key, thumbnail_object_key
  )
  select asset.id, asset.owner_id, asset.bucket, asset.object_key, asset.thumbnail_object_key
  from public.assets asset where asset.id = orphan_id
  on conflict (asset_id) do update set next_attempt_at = now(), updated_at = now();
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

create trigger asset_links_queue_orphan
after delete or update of asset_id on public.asset_links
for each row execute function public.queue_orphan_asset();

create function public.queue_deleted_asset()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  insert into public.asset_deletion_queue (
    asset_id, owner_id, bucket, object_key, thumbnail_object_key
  ) values (old.id, old.owner_id, old.bucket, old.object_key, old.thumbnail_object_key)
  on conflict (asset_id) do update set
    object_key = excluded.object_key,
    thumbnail_object_key = excluded.thumbnail_object_key,
    next_attempt_at = now(),
    updated_at = now();
  return old;
end;
$$;

create trigger assets_queue_before_delete
before delete on public.assets
for each row execute function public.queue_deleted_asset();

create trigger assets_set_updated_at before update on public.assets
for each row execute function public.set_updated_at();

create trigger asset_links_set_updated_at before update on public.asset_links
for each row execute function public.set_updated_at();

create trigger asset_deletion_queue_set_updated_at before update on public.asset_deletion_queue
for each row execute function public.set_updated_at();

alter table public.assets enable row level security;

alter table public.asset_links enable row level security;

alter table public.asset_deletion_queue enable row level security;

create policy "owners read their assets" on public.assets for select to authenticated
using (owner_id = (select app_private.app_current_user_id()));

create policy "owners read their asset links" on public.asset_links for select to authenticated
using (owner_id = (select app_private.app_current_user_id()));

comment on table public.assets is
  'Owner-scoped physical itinerary blobs; never project IDs, hashes, or object keys publicly.';

comment on table public.asset_links is
  'Per-item attachment metadata and explicit public-share opt-in.';

-- Source: supabase/migrations/20260817153531_phase_8a_attachment_rpcs.sql
-- Atomic owner attachment lifecycle and server-only access resolution.

create function public.asset_link_owner_json_v1(target_link_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'id', link.id,
    'publicRef', link.public_ref,
    'fileName', link.display_filename,
    'sortOrder', link.sort_order,
    'includeInShare', link.include_in_share,
    'kind', asset.media_kind,
    'mimeType', asset.mime_type,
    'byteSize', asset.byte_size,
    'status', asset.status,
    'width', asset.width,
    'height', asset.height,
    'durationSeconds', asset.duration_seconds,
    'createdAt', link.created_at
  )
  from public.asset_links link
  join public.assets asset on asset.id = link.asset_id
  where link.id = target_link_id;
$$;

create function public.prepare_item_asset_v1(
  target_trip_id uuid,
  target_item_id uuid,
  requested_filename text,
  requested_sha256 text,
  requested_byte_size bigint,
  requested_media_kind public.asset_media_kind,
  requested_mime_type text
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  canonical_asset public.assets%rowtype;
  prepared_asset public.assets%rowtype;
  prepared_link public.asset_links%rowtype;
  existing_link public.asset_links%rowtype;
  item_count integer;
  item_bytes bigint;
  owner_bytes bigint;
  next_order integer;
  new_asset_id uuid := gen_random_uuid();
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  if requested_filename is null
    or char_length(btrim(requested_filename)) not between 1 and 240
    or requested_filename ~ '[[:cntrl:]]' then
    raise exception 'ATTACHMENT_FILENAME_INVALID' using errcode = '22023';
  end if;
  if requested_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'ATTACHMENT_HASH_INVALID' using errcode = '22023';
  end if;
  if requested_byte_size < 1
    or (requested_media_kind = 'image' and requested_byte_size > 10485760)
    or (requested_media_kind = 'pdf' and requested_byte_size > 20971520)
    or (requested_media_kind = 'video' and requested_byte_size > 31457280) then
    raise exception 'ATTACHMENT_FILE_BYTES_LIMIT' using errcode = '22023';
  end if;
  if not (
    (requested_media_kind = 'image' and requested_mime_type in (
      'image/jpeg', 'image/png', 'image/webp'
    ))
    or (requested_media_kind = 'pdf' and requested_mime_type = 'application/pdf')
    or (requested_media_kind = 'video' and requested_mime_type in (
      'video/mp4', 'video/webm', 'video/quicktime'
    ))
  ) then
    raise exception 'ATTACHMENT_TYPE_UNSUPPORTED' using errcode = '22023';
  end if;

  perform 1
  from public.itinerary_items item
  join public.trips trip on trip.id = item.trip_id
  where item.id = target_item_id
    and item.trip_id = target_trip_id
    and trip.owner_id = current_user_id
  for update of item;
  if not found then
    raise exception 'ATTACHMENT_ITEM_OWNER_REQUIRED' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(target_item_id::text, 801));
  perform pg_advisory_xact_lock(hashtextextended(current_user_id::text, 802));

  select * into canonical_asset
  from public.assets asset
  where asset.owner_id = current_user_id
    and asset.sha256 = requested_sha256
    and asset.byte_size = requested_byte_size
    and asset.status = 'ready'
  limit 1;

  if canonical_asset.id is not null then
    select * into existing_link
    from public.asset_links link
    where link.asset_id = canonical_asset.id
      and link.itinerary_item_id = target_item_id;
    if existing_link.id is not null then
      return jsonb_build_object(
        'uploadRequired', false,
        'duplicate', true,
        'assetId', canonical_asset.id,
        'attachment', public.asset_link_owner_json_v1(existing_link.id)
      );
    end if;
  end if;

  select count(*), coalesce(sum(asset.byte_size), 0),
    coalesce(max(link.sort_order), -1) + 1
  into item_count, item_bytes, next_order
  from public.asset_links link
  join public.assets asset on asset.id = link.asset_id
  where link.itinerary_item_id = target_item_id
    and asset.status in ('pending', 'ready');
  if item_count >= 5 then
    raise exception 'ATTACHMENT_COUNT_LIMIT' using errcode = '23514';
  end if;
  if item_bytes + requested_byte_size > 52428800 then
    raise exception 'ATTACHMENT_ITEM_BYTES_LIMIT' using errcode = '23514';
  end if;

  if canonical_asset.id is not null then
    insert into public.asset_links (
      asset_id, owner_id, trip_id, itinerary_item_id, display_filename, sort_order
    ) values (
      canonical_asset.id, current_user_id, target_trip_id, target_item_id,
      btrim(requested_filename), next_order
    ) returning * into prepared_link;
    return jsonb_build_object(
      'uploadRequired', false,
      'duplicate', false,
      'assetId', canonical_asset.id,
      'attachment', public.asset_link_owner_json_v1(prepared_link.id)
    );
  end if;

  select coalesce(sum(asset.byte_size), 0) into owner_bytes
  from public.assets asset
  where asset.owner_id = current_user_id
    and asset.status in ('pending', 'ready');
  if owner_bytes + requested_byte_size > 262144000 then
    raise exception 'ATTACHMENT_OWNER_BYTES_LIMIT' using errcode = '23514';
  end if;

  insert into public.assets (
    id, owner_id, object_key, thumbnail_object_key, media_kind, mime_type,
    byte_size, sha256, pending_expires_at
  ) values (
    new_asset_id,
    current_user_id,
    current_user_id::text || '/' || new_asset_id::text || '/original',
    case requested_media_kind
      when 'image' then current_user_id::text || '/' || new_asset_id::text || '/thumbnail.webp'
      when 'video' then current_user_id::text || '/' || new_asset_id::text || '/poster.webp'
      else null
    end,
    requested_media_kind,
    requested_mime_type,
    requested_byte_size,
    requested_sha256,
    now() + interval '24 hours'
  ) returning * into prepared_asset;

  insert into public.asset_links (
    asset_id, owner_id, trip_id, itinerary_item_id, display_filename, sort_order
  ) values (
    prepared_asset.id, current_user_id, target_trip_id, target_item_id,
    btrim(requested_filename), next_order
  ) returning * into prepared_link;

  return jsonb_build_object(
    'uploadRequired', true,
    'duplicate', false,
    'assetId', prepared_asset.id,
    'objectKey', prepared_asset.object_key,
    'thumbnailObjectKey', prepared_asset.thumbnail_object_key,
    'expiresAt', prepared_asset.pending_expires_at,
    'attachment', public.asset_link_owner_json_v1(prepared_link.id)
  );
end;
$$;

create function public.finalize_item_asset_v1(
  target_asset_id uuid,
  verified_sha256 text,
  verified_byte_size bigint,
  verified_media_kind public.asset_media_kind,
  verified_mime_type text,
  verified_width integer default null,
  verified_height integer default null,
  verified_duration_seconds numeric default null,
  thumbnail_ready boolean default false
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_user_id varchar(64) := app_private.app_current_user_id();
  managed_asset public.assets%rowtype;
  canonical_asset public.assets%rowtype;
  managed_link public.asset_links%rowtype;
  link_row public.asset_links%rowtype;
  current_count integer;
  current_bytes bigint;
begin
  if current_user_id is null then
    raise exception 'AUTHENTICATION_REQUIRED' using errcode = '42501';
  end if;
  select * into managed_asset from public.assets asset
  where asset.id = target_asset_id and asset.owner_id = current_user_id
  for update;
  if managed_asset.id is null then
    raise exception 'ATTACHMENT_OWNER_REQUIRED' using errcode = '42501';
  end if;
  if managed_asset.status = 'ready' then
    select * into managed_link from public.asset_links
    where asset_id = managed_asset.id order by created_at limit 1;
    return jsonb_build_object(
      'deduplicated', false,
      'attachment', public.asset_link_owner_json_v1(managed_link.id)
    );
  end if;
  if managed_asset.status <> 'pending' then
    raise exception 'ATTACHMENT_NOT_PENDING' using errcode = '22023';
  end if;
  if managed_asset.sha256 <> verified_sha256
    or managed_asset.byte_size <> verified_byte_size
    or managed_asset.media_kind <> verified_media_kind then
    raise exception 'ATTACHMENT_VERIFICATION_MISMATCH' using errcode = '22023';
  end if;
  if not (
    (verified_media_kind = 'image' and verified_mime_type in (
      'image/jpeg', 'image/png', 'image/webp'
    ))
    or (verified_media_kind = 'pdf' and verified_mime_type = 'application/pdf')
    or (verified_media_kind = 'video' and verified_mime_type in (
      'video/mp4', 'video/webm', 'video/quicktime'
    ))
  ) then
    raise exception 'ATTACHMENT_TYPE_UNSUPPORTED' using errcode = '22023';
  end if;
  if verified_media_kind = 'image' and thumbnail_ready is false then
    raise exception 'ATTACHMENT_THUMBNAIL_REQUIRED' using errcode = '22023';
  end if;
  if not exists (select 1 from public.asset_links where asset_id = managed_asset.id) then
    raise exception 'ATTACHMENT_ITEM_DELETED' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(current_user_id::text, 802));
  select * into canonical_asset
  from public.assets asset
  where asset.owner_id = current_user_id
    and asset.sha256 = verified_sha256
    and asset.byte_size = verified_byte_size
    and asset.status = 'ready'
    and asset.id <> managed_asset.id
  limit 1;

  if canonical_asset.id is not null then
    for link_row in select * from public.asset_links where asset_id = managed_asset.id loop
      perform pg_advisory_xact_lock(hashtextextended(link_row.itinerary_item_id::text, 801));
      if exists (
        select 1 from public.asset_links existing
        where existing.asset_id = canonical_asset.id
          and existing.itinerary_item_id = link_row.itinerary_item_id
      ) then
        delete from public.asset_links where id = link_row.id;
        select * into managed_link from public.asset_links existing
        where existing.asset_id = canonical_asset.id
          and existing.itinerary_item_id = link_row.itinerary_item_id;
      else
        update public.asset_links set asset_id = canonical_asset.id
        where id = link_row.id returning * into managed_link;
      end if;
    end loop;
    update public.assets set status = 'deleting', pending_expires_at = null
    where id = managed_asset.id;
    insert into public.asset_deletion_queue (
      asset_id, owner_id, bucket, object_key, thumbnail_object_key
    ) values (
      managed_asset.id, managed_asset.owner_id, managed_asset.bucket,
      managed_asset.object_key, managed_asset.thumbnail_object_key
    ) on conflict (asset_id) do update set next_attempt_at = now(), updated_at = now();
    return jsonb_build_object(
      'deduplicated', true,
      'attachment', public.asset_link_owner_json_v1(managed_link.id)
    );
  end if;

  for link_row in select distinct on (itinerary_item_id) *
    from public.asset_links where asset_id = managed_asset.id loop
    perform pg_advisory_xact_lock(hashtextextended(link_row.itinerary_item_id::text, 801));
    select count(*), coalesce(sum(asset.byte_size), 0)
    into current_count, current_bytes
    from public.asset_links link
    join public.assets asset on asset.id = link.asset_id
    where link.itinerary_item_id = link_row.itinerary_item_id
      and asset.status in ('pending', 'ready');
    if current_count > 5 then
      raise exception 'ATTACHMENT_COUNT_LIMIT' using errcode = '23514';
    end if;
    if current_bytes > 52428800 then
      raise exception 'ATTACHMENT_ITEM_BYTES_LIMIT' using errcode = '23514';
    end if;
  end loop;

  update public.assets set
    media_kind = verified_media_kind,
    mime_type = verified_mime_type,
    byte_size = verified_byte_size,
    sha256 = verified_sha256,
    width = verified_width,
    height = verified_height,
    duration_seconds = verified_duration_seconds,
    thumbnail_object_key = case when thumbnail_ready then thumbnail_object_key else null end,
    status = 'ready',
    pending_expires_at = null,
    finalized_at = now(),
    failure_reason = null
  where id = managed_asset.id
  returning * into managed_asset;

  select * into managed_link from public.asset_links
  where asset_id = managed_asset.id order by created_at limit 1;
  return jsonb_build_object(
    'deduplicated', false,
    'attachment', public.asset_link_owner_json_v1(managed_link.id)
  );
exception
  when unique_violation then
    raise exception 'ATTACHMENT_FINALIZE_CONFLICT' using errcode = '40001';
end;
$$;

create function public.fail_item_asset_v1(target_asset_id uuid, requested_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.assets set
    status = 'failed',
    pending_expires_at = null,
    failure_reason = left(coalesce(requested_reason, 'Verification failed'), 500)
  where id = target_asset_id and owner_id = app_private.app_current_user_id() and status = 'pending';
  if found then delete from public.asset_links where asset_id = target_asset_id; end if;
end;
$$;

create function public.set_item_asset_share_v1(
  target_trip_id uuid,
  target_item_id uuid,
  requested_public_ref text,
  requested_include_in_share boolean
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  managed_link public.asset_links%rowtype;
begin
  update public.asset_links link set include_in_share = requested_include_in_share
  from public.assets asset
  where link.public_ref = requested_public_ref
    and link.trip_id = target_trip_id
    and link.itinerary_item_id = target_item_id
    and link.owner_id = app_private.app_current_user_id()
    and asset.id = link.asset_id
    and asset.status = 'ready'
  returning link.* into managed_link;
  if managed_link.id is null then
    raise exception 'ATTACHMENT_OWNER_REQUIRED' using errcode = '42501';
  end if;
  return public.asset_link_owner_json_v1(managed_link.id);
end;
$$;

create function public.detach_item_asset_v1(
  target_trip_id uuid,
  target_item_id uuid,
  requested_public_ref text
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  detached_asset_id uuid;
begin
  delete from public.asset_links link
  where link.public_ref = requested_public_ref
    and link.trip_id = target_trip_id
    and link.itinerary_item_id = target_item_id
    and link.owner_id = app_private.app_current_user_id()
  returning link.asset_id into detached_asset_id;
  if detached_asset_id is null then
    raise exception 'ATTACHMENT_OWNER_REQUIRED' using errcode = '42501';
  end if;
  return detached_asset_id;
end;
$$;

create function public.owner_asset_access_v1(
  target_trip_id uuid,
  requested_public_ref text
) returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'bucket', asset.bucket,
    'objectKey', asset.object_key,
    'thumbnailObjectKey', asset.thumbnail_object_key,
    'fileName', link.display_filename,
    'mimeType', asset.mime_type,
    'kind', asset.media_kind,
    'byteSize', asset.byte_size
  )
  from public.asset_links link
  join public.assets asset on asset.id = link.asset_id
  join public.trips trip on trip.id = link.trip_id
  where link.trip_id = target_trip_id
    and link.public_ref = requested_public_ref
    and trip.owner_id = app_private.app_current_user_id()
    and link.owner_id = app_private.app_current_user_id()
    and asset.status = 'ready';
$$;

